-- Semilla del compendio SRD 5.1 en español para Grimhold.
-- Generado por build-srd.js a partir del SRD 5.1 de Wizards of the Coast
-- (Creative Commons Attribution 4.0; servido por Open5e). Ejecutar una sola
-- vez en el SQL Editor de Supabase, después de supabase-schema.sql.

create table if not exists public.srd_monsters (
  slug text primary key,
  name text not null,
  type text not null default 'Criatura',
  size text,
  ac int not null default 10,
  hp int not null default 1,
  cr numeric not null default 0,
  data jsonb not null,
  source text not null default 'srd-5.1'
);

create table if not exists public.srd_spells (
  slug text primary key,
  name text not null,
  level int not null default 0,
  school text not null default 'Universal',
  data jsonb not null,
  source text not null default 'srd-5.1'
);

alter table public.srd_monsters enable row level security;
alter table public.srd_spells enable row level security;

drop policy if exists "Anyone authenticated can read SRD monsters" on public.srd_monsters;
drop policy if exists "Anyone authenticated can read SRD spells" on public.srd_spells;
create policy "Anyone authenticated can read SRD monsters" on public.srd_monsters
  for select to authenticated using (true);
create policy "Anyone authenticated can read SRD spells" on public.srd_spells
  for select to authenticated using (true);

grant select on public.srd_monsters to authenticated;
grant select on public.srd_spells to authenticated;

-- El seed es idempotente: limpia y recarga el compendio completo.
truncate public.srd_monsters;
truncate public.srd_spells;

on conflict (slug) do nothing;

