insert into public.srd_monsters (slug, name, type, size, ac, hp, cr, data, source)
values
  ('', 'Aboleth', 'Aberración', 'Grande', '17', '135', '10', '{"id":"srd-aboleth","name":"Aboleth","type":"Aberración","size":"Grande","ac":17,"hp":135,"speed":"10 pies, nado 40 pies","cr":10,"stats":{"str":21,"dex":9,"con":15,"int":18,"wis":15,"cha":18},"abilities":"Amphibious. The aboleth can breathe air and water. Mucous Cloud. While underwater, the aboleth is surrounded by transformative mucus. A creature that touches the aboleth or that hits it with a melee attack while within 5 ft. of it must make a DC 14 Constitution saving throw. On a failure, the creature is diseased for 1d4 hours. The diseased creature can breathe only underwater. Probing Telepathy. If a creature communicates telepathically with the aboleth, the aboleth learns the creature''s greatest desires if the aboleth can see the creature. Sentidos: darkvision 120 ft., passive Perception 20. Idiomas: Deep Speech, telepathy 120 ft. Dados de golpe: 18d10+36 Armadura: natural armor","actions":"Multiattack. The aboleth makes three tentacle attacks. Tentacle. Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 12 (2d6 + 5) bludgeoning damage. If the target is a creature, it must succeed on a DC 14 Constitution saving throw or become diseased. The disease has no effect for 1 minute and can be removed by any magic that cures disease. After 1 minute, the diseased creature''s skin becomes translucent and slimy, the creature can''t regain hit points unless it is underwater, and the disease can be removed only by heal or another disease-curing spell of 6th level or higher. When the creature is outside a body of water, it takes 6 (1d12) acid damage every 10 minutes unless moisture is applied to the skin before 10 minutes have passed. Tail. Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 15 (3d6 + 5) bludgeoning damage. Enslave (3/day). The aboleth targets one creature it can see within 30 ft. of it. The target must succeed on a DC 14 Wisdom saving throw or be magically charmed by the aboleth until the aboleth dies or until it is on a different plane of existence from the target. The charmed target is under the aboleth''s control and can''t take reactions, and the aboleth and the target can communicate telepathically with each other over any distance.\nWhenever the charmed target takes damage, the target can repeat the saving throw. On a success, the effect ends. No more than once every 24 hours, the target can also repeat the saving throw when it is at least 1 mile away from the aboleth. Detect (legendaria). The aboleth makes a Wisdom (Perception) check. Tail Swipe (legendaria). The aboleth makes one tail attack. Psychic Drain (Costs 2 Actions) (legendaria). One creature charmed by the aboleth takes 10 (3d6) psychic damage, and the aboleth regains hit points equal to the damage the creature takes. Acciones legendarias. The aboleth can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The aboleth regains spent legendary actions at the start of its turn.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Acechador invisible', 'Elemental', 'Mediano', '14', '104', '6', '{"id":"srd-invisible-stalker","name":"Acechador invisible","type":"Elemental","size":"Mediano","ac":14,"hp":104,"speed":"50 pies, vuelo 50 pies, levita","cr":6,"stats":{"str":16,"dex":19,"con":14,"int":10,"wis":15,"cha":11},"abilities":"Invisibility. The stalker is invisible. Faultless Tracker. The stalker is given a quarry by its summoner. The stalker knows the direction and distance to its quarry as long as the two of them are on the same plane of existence. The stalker also knows the location of its summoner. Sentidos: darkvision 60 ft., passive Perception 18. Idiomas: Auran, understands Common but doesn''t speak it Dados de golpe: 16d8+32","actions":"Multiattack. The stalker makes two slam attacks. Slam. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) bludgeoning damage.","alignment":"Neutral","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Acólito', 'Humanoide', 'Mediano', '10', '9', '0.25', '{"id":"srd-acolyte","name":"Acólito","type":"Humanoide","size":"Mediano","ac":10,"hp":9,"speed":"30 pies","cr":0.25,"stats":{"str":10,"dex":10,"con":10,"int":10,"wis":14,"cha":11},"abilities":"Spellcasting. The acolyte is a 1st-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 12, +4 to hit with spell attacks). The acolyte has following cleric spells prepared:\n\n* Cantrips (at will): light, sacred flame, thaumaturgy\n* 1st level (3 slots): bless, cure wounds, sanctuary Sentidos: passive Perception 12. Idiomas: any one language (usually Common) Dados de golpe: 2d8","actions":"Club. Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage.","alignment":"Cualquiera","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Águila', 'Bestia', 'Pequeño', '12', '3', '0', '{"id":"srd-eagle","name":"Águila","type":"Bestia","size":"Pequeño","ac":12,"hp":3,"speed":"10 pies, vuelo 60 pies","cr":0,"stats":{"str":6,"dex":15,"con":10,"int":2,"wis":14,"cha":7},"abilities":"Keen Sight. The eagle has advantage on Wisdom (Perception) checks that rely on sight. Sentidos: passive Perception 14 Dados de golpe: 1d6","actions":"Talons. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) slashing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Águila gigante', 'Bestia', 'Grande', '13', '26', '1', '{"id":"srd-giant-eagle","name":"Águila gigante","type":"Bestia","size":"Grande","ac":13,"hp":26,"speed":"10 pies, vuelo 80 pies","cr":1,"stats":{"str":16,"dex":17,"con":13,"int":8,"wis":14,"cha":10},"abilities":"Keen Sight. The eagle has advantage on Wisdom (Perception) checks that rely on sight. Sentidos: passive Perception 14. Idiomas: Giant Eagle, understands Common and Auran but can''t speak Dados de golpe: 4d10+4","actions":"Multiattack. The eagle makes two attacks: one with its beak and one with its talons. Beak. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage. Talons. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage.","alignment":"Neutral bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Alce', 'Bestia', 'Grande', '10', '13', '0.25', '{"id":"srd-elk","name":"Alce","type":"Bestia","size":"Grande","ac":10,"hp":13,"speed":"50 pies","cr":0.25,"stats":{"str":16,"dex":10,"con":12,"int":2,"wis":10,"cha":6},"abilities":"Charge. If the elk moves at least 20 ft. straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 (2d6) damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone. Sentidos: passive Perception 10 Dados de golpe: 2d10+2","actions":"Ram. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) bludgeoning damage. Hooves. Melee Weapon Attack: +5 to hit, reach 5 ft., one prone creature. Hit: 8 (2d4 + 3) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Alce gigante', 'Bestia', 'Enorme', '15', '42', '2', '{"id":"srd-giant-elk","name":"Alce gigante","type":"Bestia","size":"Enorme","ac":15,"hp":42,"speed":"60 pies","cr":2,"stats":{"str":19,"dex":16,"con":14,"int":7,"wis":14,"cha":10},"abilities":"Charge. If the elk moves at least 20 ft. straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 (2d6) damage. If the target is a creature, it must succeed on a DC 14 Strength saving throw or be knocked prone. Sentidos: passive Perception 14. Idiomas: Giant Elk, understands Common, Elvish, and Sylvan but can''t speak Dados de golpe: 5d12+10 Armadura: natural armor","actions":"Ram. Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage. Hooves. Melee Weapon Attack: +6 to hit, reach 5 ft., one prone creature. Hit: 22 (4d8 + 4) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Alfombra asfixiante', 'Constructo', 'Grande', '12', '33', '2', '{"id":"srd-rug-of-smothering","name":"Alfombra asfixiante","type":"Constructo","size":"Grande","ac":12,"hp":33,"speed":"10 pies","cr":2,"stats":{"str":17,"dex":14,"con":10,"int":1,"wis":3,"cha":1},"abilities":"Antimagic Susceptibility. The rug is incapacitated while in the area of an antimagic field. If targeted by dispel magic, the rug must succeed on a Constitution saving throw against the caster''s spell save DC or fall unconscious for 1 minute. Damage Transfer. While it is grappling a creature, the rug takes only half the damage dealt to it, and the creature grappled by the rug takes the other half. False Appearance. While the rug remains motionless, it is indistinguishable from a normal rug. Sentidos: blindsight 60 ft. (blind beyond this radius), passive Perception 6 Dados de golpe: 6d10","actions":"Smother. Melee Weapon Attack: +5 to hit, reach 5 ft., one Medium or smaller creature. Hit: The creature is grappled (escape DC 13). Until this grapple ends, the target is restrained, blinded, and at risk of suffocating, and the rug can''t smother another target. In addition, at the start of each of the target''s turns, the target takes 10 (2d6 + 3) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Androesfinge', 'Monstruosidad', 'Grande', '17', '199', '17', '{"id":"srd-androsphinx","name":"Androesfinge","type":"Monstruosidad","size":"Grande","ac":17,"hp":199,"speed":"40 pies, vuelo 60 pies","cr":17,"stats":{"str":22,"dex":10,"con":20,"int":16,"wis":18,"cha":23},"abilities":"Inscrutable. The sphinx is immune to any effect that would sense its emotions or read its thoughts, as well as any divination spell that it refuses. Wisdom (Insight) checks made to ascertain the sphinx''s intentions or sincerity have disadvantage. Magic Weapons. The sphinx''s weapon attacks are magical. Spellcasting. The sphinx is a 12th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 18, +10 to hit with spell attacks). It requires no material components to cast its spells. The sphinx has the following cleric spells prepared:\n\n* Cantrips (at will): sacred flame, spare the dying, thaumaturgy\n* 1st level (4 slots): command, detect evil and good, detect magic\n* 2nd level (3 slots): lesser restoration, zone of truth\n* 3rd level (3 slots): dispel magic, tongues\n* 4th level (3 slots): banishment, freedom of movement\n* 5th level (2 slots): flame strike, greater restoration\n* 6th level (1 slot): heroes'' feast Sentidos: truesight 120 ft., passive Perception 20. Idiomas: Common, Sphinx Dados de golpe: 19d10+95 Armadura: natural armor","actions":"Multiattack. The sphinx makes two claw attacks. Claw. Melee Weapon Attack: +12 to hit, reach 5 ft., one target. Hit: 17 (2d10 + 6) slashing damage. Roar (3/Day). The sphinx emits a magical roar. Each time it roars before finishing a long rest, the roar is louder and the effect is different, as detailed below. Each creature within 500 feet of the sphinx and able to hear the roar must make a saving throw.\n**First Roar.** Each creature that fails a DC 18 Wisdom saving throw is frightened for 1 minute. A frightened creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\n**Second Roar.** Each creature that fails a DC 18 Wisdom saving throw is deafened and frightened for 1 minute. A frightened creature is paralyzed and can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\n**Third Roar.** Each creature makes a DC 18 Constitution saving throw. On a failed save, a creature takes 44 (8d10) thunder damage and is knocked prone. On a successful save, the creature takes half as much damage and isn''t knocked prone. Claw Attack (legendaria). The sphinx makes one claw attack. Teleport (Costs 2 Actions) (legendaria). The sphinx magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see. Cast a Spell (Costs 3 Actions) (legendaria). The sphinx casts a spell from its list of prepared spells, using a spell slot as normal. Acciones legendarias. The sphinx can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The sphinx regains spent legendary actions at the start of its turn.","alignment":"Legal neutral","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Ankheg', 'Monstruosidad', 'Grande', '14', '39', '2', '{"id":"srd-ankheg","name":"Ankheg","type":"Monstruosidad","size":"Grande","ac":14,"hp":39,"speed":"30 pies, excavación 10 pies","cr":2,"stats":{"str":17,"dex":11,"con":13,"int":1,"wis":13,"cha":6},"abilities":"Sentidos: darkvision 60 ft., tremorsense 60 ft., passive Perception 11 Dados de golpe: 6d10+6 Armadura: 14 (natural armor), 11 while prone","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage plus 3 (1d6) acid damage. If the target is a Large or smaller creature, it is grappled (escape DC 13). Until this grapple ends, the ankheg can bite only the grappled creature and has advantage on attack rolls to do so. Acid Spray (Recharge 6). The ankheg spits acid in a line that is 30 ft. long and 5 ft. wide, provided that it has no creature grappled. Each creature in that line must make a DC 13 Dexterity saving throw, taking 10 (3d6) acid damage on a failed save, or half as much damage on a successful one.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Araña', 'Bestia', 'Diminuto', '12', '1', '0', '{"id":"srd-spider","name":"Araña","type":"Bestia","size":"Diminuto","ac":12,"hp":1,"speed":"20 pies, escalada 20 pies","cr":0,"stats":{"str":2,"dex":14,"con":8,"int":1,"wis":10,"cha":2},"abilities":"Spider Climb. The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check. Web Sense. While in contact with a web, the spider knows the exact location of any other creature in contact with the same web. Web Walker. The spider ignores movement restrictions caused by webbing. Sentidos: darkvision 30 ft., passive Perception 12 Dados de golpe: 1d4-1","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 1 piercing damage, and the target must succeed on a DC 9 Constitution saving throw or take 2 (1d4) poison damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Araña fasal', 'Monstruosidad', 'Grande', '13', '32', '3', '{"id":"srd-phase-spider","name":"Araña fasal","type":"Monstruosidad","size":"Grande","ac":13,"hp":32,"speed":"30 pies, escalada 30 pies","cr":3,"stats":{"str":15,"dex":15,"con":12,"int":6,"wis":10,"cha":6},"abilities":"Ethereal Jaunt. As a bonus action, the spider can magically shift from the Material Plane to the Ethereal Plane, or vice versa. Spider Climb. The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check. Web Walker. The spider ignores movement restrictions caused by webbing. Sentidos: darkvision 60 ft., passive Perception 10 Dados de golpe: 5d10+5 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 7 (1d10 + 2) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 18 (4d8) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Araña gigante', 'Bestia', 'Grande', '14', '26', '1', '{"id":"srd-giant-spider","name":"Araña gigante","type":"Bestia","size":"Grande","ac":14,"hp":26,"speed":"30 pies, escalada 30 pies","cr":1,"stats":{"str":14,"dex":16,"con":12,"int":2,"wis":11,"cha":4},"abilities":"Spider Climb. The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check. Web Sense. While in contact with a web, the spider knows the exact location of any other creature in contact with the same web. Web Walker. The spider ignores movement restrictions caused by webbing. Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 10 Dados de golpe: 4d10+4 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 7 (1d8 + 3) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 9 (2d8) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way. Web (Recharge 5-6). Ranged Weapon Attack: +5 to hit, range 30/60 ft., one creature. Hit: The target is restrained by webbing. As an action, the restrained target can make a DC 12 Strength check, bursting the webbing on a success. The webbing can also be attacked and destroyed (AC 10; hp 5; vulnerability to fire damage; immunity to bludgeoning, poison, and psychic damage).","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Araña lobo gigante', 'Bestia', 'Mediano', '13', '11', '0.25', '{"id":"srd-giant-wolf-spider","name":"Araña lobo gigante","type":"Bestia","size":"Mediano","ac":13,"hp":11,"speed":"40 pies, escalada 40 pies","cr":0.25,"stats":{"str":12,"dex":16,"con":13,"int":3,"wis":12,"cha":4},"abilities":"Spider Climb. The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check. Web Sense. While in contact with a web, the spider knows the exact location of any other creature in contact with the same web. Web Walker. The spider ignores movement restrictions caused by webbing. Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 13 Dados de golpe: 2d8+2","actions":"Bite. Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 4 (1d6 + 1) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 7 (2d6) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Árbol despierto', 'Planta', 'Enorme', '13', '59', '2', '{"id":"srd-awakened-tree","name":"Árbol despierto","type":"Planta","size":"Enorme","ac":13,"hp":59,"speed":"20 pies","cr":2,"stats":{"str":19,"dex":6,"con":15,"int":10,"wis":10,"cha":7},"abilities":"False Appearance. While the tree remains motionless, it is indistinguishable from a normal tree. Sentidos: passive Perception 10. Idiomas: one language known by its creator Dados de golpe: 7d12+14 Armadura: natural armor","actions":"Slam. Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 14 (3d6 + 4) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Arbusto despierto', 'Planta', 'Pequeño', '9', '10', '0', '{"id":"srd-awakened-shrub","name":"Arbusto despierto","type":"Planta","size":"Pequeño","ac":9,"hp":10,"speed":"20 pies","cr":0,"stats":{"str":3,"dex":8,"con":11,"int":10,"wis":10,"cha":6},"abilities":"False Appearance. While the shrub remains motionless, it is indistinguishable from a normal shrub. Sentidos: passive Perception 10. Idiomas: one language known by its creator Dados de golpe: 3d6","actions":"Rake. Melee Weapon Attack: +1 to hit, reach 5 ft., one target. Hit: 1 (1d4 - 1) slashing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Armadura animada', 'Constructo', 'Mediano', '18', '33', '1', '{"id":"srd-animated-armor","name":"Armadura animada","type":"Constructo","size":"Mediano","ac":18,"hp":33,"speed":"25 pies","cr":1,"stats":{"str":14,"dex":11,"con":13,"int":1,"wis":3,"cha":1},"abilities":"Antimagic Susceptibility. The armor is incapacitated while in the area of an antimagic field. If targeted by dispel magic, the armor must succeed on a Constitution saving throw against the caster''s spell save DC or fall unconscious for 1 minute. False Appearance. While the armor remains motionless, it is indistinguishable from a normal suit of armor. Sentidos: blindsight 60 ft. (blind beyond this radius), passive Perception 6 Dados de golpe: 6d8+6 Armadura: natural armor","actions":"Multiattack. The armor makes two melee attacks. Slam. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Arpía', 'Monstruosidad', 'Mediano', '11', '38', '1', '{"id":"srd-harpy","name":"Arpía","type":"Monstruosidad","size":"Mediano","ac":11,"hp":38,"speed":"20 pies, vuelo 40 pies","cr":1,"stats":{"str":12,"dex":13,"con":12,"int":7,"wis":10,"cha":13},"abilities":"Sentidos: passive Perception 10. Idiomas: Common Dados de golpe: 7d8+7","actions":"Multiattack. The harpy makes two attacks: one with its claws and one with its club. Claws. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 6 (2d4 + 1) slashing damage. Club. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 1) bludgeoning damage. Luring Song. The harpy sings a magical melody. Every humanoid and giant within 300 ft. of the harpy that can hear the song must succeed on a DC 11 Wisdom saving throw or be charmed until the song ends. The harpy must take a bonus action on its subsequent turns to continue singing. It can stop singing at any time. The song ends if the harpy is incapacitated.\nWhile charmed by the harpy, a target is incapacitated and ignores the songs of other harpies. If the charmed target is more than 5 ft. away from the harpy, the must move on its turn toward the harpy by the most direct route. It doesn''t avoid opportunity attacks, but before moving into damaging terrain, such as lava or a pit, and whenever it takes damage from a source other than the harpy, a target can repeat the saving throw. A creature can also repeat the saving throw at the end of each of its turns. If a creature''s saving throw is successful, the effect ends on it.\nA target that successfully saves is immune to this harpy''s song for the next 24 hours.","alignment":"Caótico maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Arquimago', 'Humanoide', 'Mediano', '12', '99', '12', '{"id":"srd-archmage","name":"Arquimago","type":"Humanoide","size":"Mediano","ac":12,"hp":99,"speed":"30 pies","cr":12,"stats":{"str":10,"dex":14,"con":12,"int":20,"wis":15,"cha":16},"abilities":"Magic Resistance. The archmage has advantage on saving throws against spells and other magical effects. Spellcasting. The archmage is an 18th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 17, +9 to hit with spell attacks). The archmage can cast disguise self and invisibility at will and has the following wizard spells prepared:\n\n* Cantrips (at will): fire bolt, light, mage hand, prestidigitation, shocking grasp\n* 1st level (4 slots): detect magic, identify, mage armor*, magic missile\n* 2nd level (3 slots): detect thoughts, mirror image, misty step\n* 3rd level (3 slots): counterspell,fly, lightning bolt\n* 4th level (3 slots): banishment, fire shield, stoneskin*\n* 5th level (3 slots): cone of cold, scrying, wall of force\n* 6th level (1 slot): globe of invulnerability\n* 7th level (1 slot): teleport\n* 8th level (1 slot): mind blank*\n* 9th level (1 slot): time stop\n* The archmage casts these spells on itself before combat. Sentidos: passive Perception 12. Idiomas: any six languages Dados de golpe: 18d8+18 Armadura: 15 with _mage armor_","actions":"Dagger. Melee or Ranged Weapon Attack: +6 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","alignment":"Cualquiera","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Asesino', 'Humanoide', 'Mediano', '15', '78', '8', '{"id":"srd-assassin","name":"Asesino","type":"Humanoide","size":"Mediano","ac":15,"hp":78,"speed":"30 pies","cr":8,"stats":{"str":11,"dex":16,"con":14,"int":13,"wis":11,"cha":10},"abilities":"Assassinate. During its first turn, the assassin has advantage on attack rolls against any creature that hasn''t taken a turn. Any hit the assassin scores against a surprised creature is a critical hit. Evasion. If the assassin is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the assassin instead takes no damage if it succeeds on the saving throw, and only half damage if it fails. Sneak Attack (1/Turn). The assassin deals an extra 13 (4d6) damage when it hits a target with a weapon attack and has advantage on the attack roll, or when the target is within 5 ft. of an ally of the assassin that isn''t incapacitated and the assassin doesn''t have disadvantage on the attack roll. Sentidos: passive Perception 13. Idiomas: Thieves'' cant plus any two languages Dados de golpe: 12d8+24 Armadura: studded leather","actions":"Multiattack. The assassin makes two shortsword attacks. Shortsword. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage, and the target must make a DC 15 Constitution saving throw, taking 24 (7d6) poison damage on a failed save, or half as much damage on a successful one. Light Crossbow. Ranged Weapon Attack: +6 to hit, range 80/320 ft., one target. Hit: 7 (1d8 + 3) piercing damage, and the target must make a DC 15 Constitution saving throw, taking 24 (7d6) poison damage on a failed save, or half as much damage on a successful one.","alignment":"Cualquiera no bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Avispa gigante', 'Bestia', 'Mediano', '12', '13', '0.5', '{"id":"srd-giant-wasp","name":"Avispa gigante","type":"Bestia","size":"Mediano","ac":12,"hp":13,"speed":"10 pies, vuelo 50 pies","cr":0.5,"stats":{"str":10,"dex":14,"con":10,"int":1,"wis":10,"cha":3},"abilities":"Sentidos: passive Perception 10 Dados de golpe: 3d8","actions":"Sting. Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 10 (3d6) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Azer', 'Elemental', 'Mediano', '17', '39', '2', '{"id":"srd-azer","name":"Azer","type":"Elemental","size":"Mediano","ac":17,"hp":39,"speed":"30 pies","cr":2,"stats":{"str":17,"dex":12,"con":15,"int":12,"wis":13,"cha":10},"abilities":"Heated Body. A creature that touches the azer or hits it with a melee attack while within 5 ft. of it takes 5 (1d10) fire damage. Heated Weapons. When the azer hits with a metal melee weapon, it deals an extra 3 (1d6) fire damage (included in the attack). Illumination. The azer sheds bright light in a 10-foot radius and dim light for an additional 10 ft.. Sentidos: passive Perception 11. Idiomas: Ignan Dados de golpe: 6d8+12 Armadura: natural armor, shield","actions":"Warhammer. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) bludgeoning damage, or 8 (1d10 + 3) bludgeoning damage if used with two hands to make a melee attack, plus 3 (1d6) fire damage.","alignment":"Legal neutral","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Babuino', 'Bestia', 'Pequeño', '12', '3', '0', '{"id":"srd-baboon","name":"Babuino","type":"Bestia","size":"Pequeño","ac":12,"hp":3,"speed":"30 pies, escalada 30 pies","cr":0,"stats":{"str":8,"dex":14,"con":11,"int":4,"wis":12,"cha":6},"abilities":"Pack Tactics. The baboon has advantage on an attack roll against a creature if at least one of the baboon''s allies is within 5 ft. of the creature and the ally isn''t incapacitated. Sentidos: passive Perception 11 Dados de golpe: 1d6","actions":"Bite. Melee Weapon Attack: +1 to hit, reach 5 ft., one target. Hit: 1 (1d4 - 1) piercing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Balor', 'Demonio', 'Enorme', '19', '262', '19', '{"id":"srd-balor","name":"Balor","type":"Demonio","size":"Enorme","ac":19,"hp":262,"speed":"40 pies, vuelo 80 pies","cr":19,"stats":{"str":26,"dex":15,"con":22,"int":20,"wis":16,"cha":22},"abilities":"Death Throes. When the balor dies, it explodes, and each creature within 30 feet of it must make a DC 20 Dexterity saving throw, taking 70 (20d6) fire damage on a failed save, or half as much damage on a successful one. The explosion ignites flammable objects in that area that aren''t being worn or carried, and it destroys the balor''s weapons. Fire Aura. At the start of each of the balor''s turns, each creature within 5 feet of it takes 10 (3d6) fire damage, and flammable objects in the aura that aren''t being worn or carried ignite. A creature that touches the balor or hits it with a melee attack while within 5 feet of it takes 10 (3d6) fire damage. Magic Resistance. The balor has advantage on saving throws against spells and other magical effects. Magic Weapons. The balor''s weapon attacks are magical. Sentidos: truesight 120 ft., passive Perception 13. Idiomas: Abyssal, telepathy 120 ft. Dados de golpe: 21d12+126 Armadura: natural armor","actions":"Multiattack. The balor makes two attacks: one with its longsword and one with its whip. Longsword. Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 21 (3d8 + 8) slashing damage plus 13 (3d8) lightning damage. If the balor scores a critical hit, it rolls damage dice three times, instead of twice. Whip. Melee Weapon Attack: +14 to hit, reach 30 ft., one target. Hit: 15 (2d6 + 8) slashing damage plus 10 (3d6) fire damage, and the target must succeed on a DC 20 Strength saving throw or be pulled up to 25 feet toward the balor. Teleport. The balor magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see. Variant: Summon Demon (1/Day). The demon chooses what to summon and attempts a magical summoning.\nA balor has a 50 percent chance of summoning 1d8 vrocks, 1d6 hezrous, 1d4 glabrezus, 1d3 nalfeshnees, 1d2 mariliths, or one goristro.\nA summoned demon appears in an unoccupied space within 60 feet of its summoner, acts as an ally of its summoner, and can''t summon other demons. It remains for 1 minute, until it or its summoner dies, or until its summoner dismisses it as an action.","alignment":"Caótico maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Bandido', 'Humanoide', 'Mediano', '12', '11', '0.125', '{"id":"srd-bandit","name":"Bandido","type":"Humanoide","size":"Mediano","ac":12,"hp":11,"speed":"30 pies","cr":0.125,"stats":{"str":11,"dex":12,"con":12,"int":10,"wis":10,"cha":10},"abilities":"Sentidos: passive Perception 10. Idiomas: any one language (usually Common) Dados de golpe: 2d8+2 Armadura: leather armor","actions":"Scimitar. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) slashing damage. Light Crossbow. Ranged Weapon Attack: +3 to hit, range 80/320 ft., one target. Hit: 5 (1d8 + 1) piercing damage.","alignment":"Cualquiera no legal","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Basilisco', 'Monstruosidad', 'Mediano', '12', '52', '3', '{"id":"srd-basilisk","name":"Basilisco","type":"Monstruosidad","size":"Mediano","ac":12,"hp":52,"speed":"20 pies","cr":3,"stats":{"str":16,"dex":8,"con":15,"int":2,"wis":8,"cha":7},"abilities":"Petrifying Gaze. If a creature starts its turn within 30 ft. of the basilisk and the two of them can see each other, the basilisk can force the creature to make a DC 12 Constitution saving throw if the basilisk isn''t incapacitated. On a failed save, the creature magically begins to turn to stone and is restrained. It must repeat the saving throw at the end of its next turn. On a success, the effect ends. On a failure, the creature is petrified until freed by the greater restoration spell or other magic.\nA creature that isn''t surprised can avert its eyes to avoid the saving throw at the start of its turn. If it does so, it can''t see the basilisk until the start of its next turn, when it can avert its eyes again. If it looks at the basilisk in the meantime, it must immediately make the save.\nIf the basilisk sees its reflection within 30 ft. of it in bright light, it mistakes itself for a rival and targets itself with its gaze. Sentidos: darkvision 60 ft., passive Perception 9 Dados de golpe: 8d8+16 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage plus 7 (2d6) poison damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Behir', 'Monstruosidad', 'Enorme', '17', '168', '11', '{"id":"srd-behir","name":"Behir","type":"Monstruosidad","size":"Enorme","ac":17,"hp":168,"speed":"50 pies, escalada 40 pies","cr":11,"stats":{"str":23,"dex":16,"con":18,"int":7,"wis":14,"cha":12},"abilities":"Sentidos: darkvision 90 ft., passive Perception 16. Idiomas: Draconic Dados de golpe: 16d12+64 Armadura: natural armor","actions":"Multiattack. The behir makes two attacks: one with its bite and one to constrict. Bite. Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 22 (3d10 + 6) piercing damage. Constrict. Melee Weapon Attack: +10 to hit, reach 5 ft., one Large or smaller creature. Hit: 17 (2d10 + 6) bludgeoning damage plus 17 (2d10 + 6) slashing damage. The target is grappled (escape DC 16) if the behir isn''t already constricting a creature, and the target is restrained until this grapple ends. Lightning Breath (Recharge 5-6). The behir exhales a line of lightning that is 20 ft. long and 5 ft. wide. Each creature in that line must make a DC 16 Dexterity saving throw, taking 66 (12d10) lightning damage on a failed save, or half as much damage on a successful one. Swallow. The behir makes one bite attack against a Medium or smaller target it is grappling. If the attack hits, the target is also swallowed, and the grapple ends. While swallowed, the target is blinded and restrained, it has total cover against attacks and other effects outside the behir, and it takes 21 (6d6) acid damage at the start of each of the behir''s turns. A behir can have only one creature swallowed at a time.\nIf the behir takes 30 damage or more on a single turn from the swallowed creature, the behir must succeed on a DC 14 Constitution saving throw at the end of that turn or regurgitate the creature, which falls prone in a space within 10 ft. of the behir. If the behir dies, a swallowed creature is no longer restrained by it and can escape from the corpse by using 15 ft. of movement, exiting prone.","alignment":"Neutral maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Berserker', 'Humanoide', 'Mediano', '13', '67', '2', '{"id":"srd-berserker","name":"Berserker","type":"Humanoide","size":"Mediano","ac":13,"hp":67,"speed":"30 pies","cr":2,"stats":{"str":16,"dex":12,"con":17,"int":9,"wis":11,"cha":9},"abilities":"Reckless. At the start of its turn, the berserker can gain advantage on all melee weapon attack rolls during that turn, but attack rolls against it have advantage until the start of its next turn. Sentidos: passive Perception 10. Idiomas: any one language (usually Common) Dados de golpe: 9d8+27 Armadura: hide armor","actions":"Greataxe. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 9 (1d12 + 3) slashing damage.","alignment":"Cualquiera caótico","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Boca balbuceante', 'Aberración', 'Mediano', '9', '67', '2', '{"id":"srd-gibbering-mouther","name":"Boca balbuceante","type":"Aberración","size":"Mediano","ac":9,"hp":67,"speed":"10 pies, nado 10 pies","cr":2,"stats":{"str":10,"dex":8,"con":16,"int":3,"wis":10,"cha":6},"abilities":"Aberrant Ground. The ground in a 10-foot radius around the mouther is doughlike difficult terrain. Each creature that starts its turn in that area must succeed on a DC 10 Strength saving throw or have its speed reduced to 0 until the start of its next turn. Gibbering. The mouther babbles incoherently while it can see any creature and isn''t incapacitated. Each creature that starts its turn within 20 feet of the mouther and can hear the gibbering must succeed on a DC 10 Wisdom saving throw. On a failure, the creature can''t take reactions until the start of its next turn and rolls a d8 to determine what it does during its turn. On a 1 to 4, the creature does nothing. On a 5 or 6, the creature takes no action or bonus action and uses all its movement to move in a randomly determined direction. On a 7 or 8, the creature makes a melee attack against a randomly determined creature within its reach or does nothing if it can''t make such an attack. Sentidos: darkvision 60 ft., passive Perception 10 Dados de golpe: 9d8+27","actions":"Multiattack. The gibbering mouther makes one bite attack and, if it can, uses its Blinding Spittle. Bites. Melee Weapon Attack: +2 to hit, reach 5 ft., one creature. Hit: 17 (5d6) piercing damage. If the target is Medium or smaller, it must succeed on a DC 10 Strength saving throw or be knocked prone. If the target is killed by this damage, it is absorbed into the mouther. Blinding Spittle (Recharge 5-6). The mouther spits a chemical glob at a point it can see within 15 feet of it. The glob explodes in a blinding flash of light on impact. Each creature within 5 feet of the flash must succeed on a DC 13 Dexterity saving throw or be blinded until the end of the mouther''s next turn.","alignment":"Neutral","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Bruja del mar', 'Hada', 'Mediano', '14', '52', '2', '{"id":"srd-sea-hag","name":"Bruja del mar","type":"Hada","size":"Mediano","ac":14,"hp":52,"speed":"30 pies, nado 40 pies","cr":2,"stats":{"str":16,"dex":13,"con":16,"int":12,"wis":12,"cha":13},"abilities":"Amphibious. The hag can breathe air and water. Horrific Appearance. Any humanoid that starts its turn within 30 feet of the hag and can see the hag''s true form must make a DC 11 Wisdom saving throw. On a failed save, the creature is frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, with disadvantage if the hag is within line of sight, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the hag''s Horrific Appearance for the next 24 hours.\nUnless the target is surprised or the revelation of the hag''s true form is sudden, the target can avert its eyes and avoid making the initial saving throw. Until the start of its next turn, a creature that averts its eyes has disadvantage on attack rolls against the hag. Hag Coven. When hags must work together, they form covens, in spite of their selfish natures. A coven is made up of hags of any type, all of whom are equals within the group. However, each of the hags continues to desire more personal power.\nA coven consists of three hags so that any arguments between two hags can be settled by the third. If more than three hags ever come together, as might happen if two covens come into conflict, the result is usually chaos. Shared Spellcasting (Coven Only). While all three members of a hag coven are within 30 feet of one another, they can each cast the following spells from the wizard''s spell list but must share the spell slots among themselves:\n\n* 1st level (4 slots): identify, ray of sickness\n* 2nd level (3 slots): hold person, locate object\n* 3rd level (3 slots): bestow curse, counterspell, lightning bolt\n* 4th level (3 slots): phantasmal killer, polymorph\n* 5th level (2 slots): contact other plane, scrying\n* 6th level (1 slot): eye bite\n\nFor casting these spells, each hag is a 12th-level spellcaster that uses Intelligence as her spellcasting ability. The spell save DC is 12+the hag''s Intelligence modifier, and the spell attack bonus is 4+the hag''s Intelligence modifier. Hag Eye (Coven Only). A hag coven can craft a magic item called a hag eye, which is made from a real eye coated in varnish and often fitted to a pendant or other wearable item. The hag eye is usually entrusted to a minion for safekeeping and transport. A hag in the coven can take an action to see what the hag eye sees if the hag eye is on the same plane of existence. A hag eye has AC 10, 1 hit point, and darkvision with a radius of 60 feet. If it is destroyed, each coven member takes 3d10 psychic damage and is blinded for 24 hours.\nA hag coven can have only one hag eye at a time, and creating a new one requires all three members of the coven to perform a ritual. The ritual takes 1 hour, and the hags can''t perform it while blinded. During the ritual, if the hags take any action other than performing the ritual, they must start over. Sentidos: darkvision 60 ft., passive Perception 11. Idiomas: Aquan, Common, Giant Dados de golpe: 7d8+21 Armadura: natural armor","actions":"Claws. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage. Death Glare. The hag targets one frightened creature she can see within 30 ft. of her. If the target can see the hag, it must succeed on a DC 11 Wisdom saving throw against this magic or drop to 0 hit points. Illusory Appearance. The hag covers herself and anything she is wearing or carrying with a magical illusion that makes her look like an ugly creature of her general size and humanoid shape. The effect ends if the hag takes a bonus action to end it or if she dies.\nThe changes wrought by this effect fail to hold up to physical inspection. For example, the hag could appear to have no claws, but someone touching her hand might feel the claws. Otherwise, a creature must take an action to visually inspect the illusion and succeed on a DC 16 Intelligence (Investigation) check to discern that the hag is disguised.","alignment":"Caótico maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Bruja nocturna', 'Demonio', 'Mediano', '17', '112', '5', '{"id":"srd-night-hag","name":"Bruja nocturna","type":"Demonio","size":"Mediano","ac":17,"hp":112,"speed":"30 pies","cr":5,"stats":{"str":18,"dex":15,"con":16,"int":16,"wis":14,"cha":16},"abilities":"Innate Spellcasting. The hag''s innate spellcasting ability is Charisma (spell save DC 14, +6 to hit with spell attacks). She can innately cast the following spells, requiring no material components:\n\nAt will: detect magic, magic missile\n2/day each: plane shift (self only), ray of enfeeblement, sleep Magic Resistance. The hag has advantage on saving throws against spells and other magical effects. Night Hag Items. A night hag carries two very rare magic items that she must craft for herself If either object is lost, the night hag will go to great lengths to retrieve it, as creating a new tool takes time and effort.\nHeartstone: This lustrous black gem allows a night hag to become ethereal while it is in her possession. The touch of a heartstone also cures any disease. Crafting a heartstone takes 30 days.\nSoul Bag: When an evil humanoid dies as a result of a night hag''s Nightmare Haunting, the hag catches the soul in this black sack made of stitched flesh. A soul bag can hold only one evil soul at a time, and only the night hag who crafted the bag can catch a soul with it. Crafting a soul bag takes 7 days and a humanoid sacrifice (whose flesh is used to make the bag). Hag Coven. When hags must work together, they form covens, in spite of their selfish natures. A coven is made up of hags of any type, all of whom are equals within the group. However, each of the hags continues to desire more personal power.\nA coven consists of three hags so that any arguments between two hags can be settled by the third. If more than three hags ever come together, as might happen if two covens come into conflict, the result is usually chaos. Shared Spellcasting (Coven Only). While all three members of a hag coven are within 30 feet of one another, they can each cast the following spells from the wizard''s spell list but must share the spell slots among themselves:\n\n* 1st level (4 slots): identify, ray of sickness\n* 2nd level (3 slots): hold person, locate object\n* 3rd level (3 slots): bestow curse, counterspell, lightning bolt\n* 4th level (3 slots): phantasmal killer, polymorph\n* 5th level (2 slots): contact other plane, scrying\n* 6th level (1 slot): eye bite\n\nFor casting these spells, each hag is a 12th-level spellcaster that uses Intelligence as her spellcasting ability. The spell save DC is 12+the hag''s Intelligence modifier, and the spell attack bonus is 4+the hag''s Intelligence modifier. Hag Eye (Coven Only). A hag coven can craft a magic item called a hag eye, which is made from a real eye coated in varnish and often fitted to a pendant or other wearable item. The hag eye is usually entrusted to a minion for safekeeping and transport. A hag in the coven can take an action to see what the hag eye sees if the hag eye is on the same plane of existence. A hag eye has AC 10, 1 hit point, and darkvision with a radius of 60 feet. If it is destroyed, each coven member takes 3d10 psychic damage and is blinded for 24 hours.\nA hag coven can have only one hag eye at a time, and creating a new one requires all three members of the coven to perform a ritual. The ritual takes 1 hour, and the hags can''t perform it while blinded. During the ritual, if the hags take any action other than performing the ritual, they must start over. Sentidos: darkvision 120 ft., passive Perception 16. Idiomas: Abyssal, Common, Infernal, Primordial Dados de golpe: 15d8+45 Armadura: natural armor","actions":"Claws (Hag Form Only). Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage. Change Shape. The hag magically polymorphs into a Small or Medium female humanoid, or back into her true form. Her statistics are the same in each form. Any equipment she is wearing or carrying isn''t transformed. She reverts to her true form if she dies. Etherealness. The hag magically enters the Ethereal Plane from the Material Plane, or vice versa. To do so, the hag must have a heartstone in her possession. Nightmare Haunting (1/Day). While on the Ethereal Plane, the hag magically touches a sleeping humanoid on the Material Plane. A protection from evil and good spell cast on the target prevents this contact, as does a magic circle. As long as the contact persists, the target has dreadful visions. If these visions last for at least 1 hour, the target gains no benefit from its rest, and its hit point maximum is reduced by 5 (1d10). If this effect reduces the target''s hit point maximum to 0, the target dies, and if the target was evil, its soul is trapped in the hag''s soul bag. The reduction to the target''s hit point maximum lasts until removed by the greater restoration spell or similar magic.","alignment":"Neutral maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Bruja verde', 'Hada', 'Mediano', '17', '82', '3', '{"id":"srd-green-hag","name":"Bruja verde","type":"Hada","size":"Mediano","ac":17,"hp":82,"speed":"30 pies","cr":3,"stats":{"str":18,"dex":12,"con":16,"int":13,"wis":14,"cha":14},"abilities":"Amphibious. The hag can breathe air and water. Innate Spellcasting. The hag''s innate spellcasting ability is Charisma (spell save DC 12). She can innately cast the following spells, requiring no material components:\n\nAt will: dancing lights, minor illusion, vicious mockery Mimicry. The hag can mimic animal sounds and humanoid voices. A creature that hears the sounds can tell they are imitations with a successful DC 14 Wisdom (Insight) check. Hag Coven. When hags must work together, they form covens, in spite of their selfish natures. A coven is made up of hags of any type, all of whom are equals within the group. However, each of the hags continues to desire more personal power.\nA coven consists of three hags so that any arguments between two hags can be settled by the third. If more than three hags ever come together, as might happen if two covens come into conflict, the result is usually chaos. Shared Spellcasting (Coven Only). While all three members of a hag coven are within 30 feet of one another, they can each cast the following spells from the wizard''s spell list but must share the spell slots among themselves:\n\n* 1st level (4 slots): identify, ray of sickness\n* 2nd level (3 slots): hold person, locate object\n* 3rd level (3 slots): bestow curse, counterspell, lightning bolt\n* 4th level (3 slots): phantasmal killer, polymorph\n* 5th level (2 slots): contact other plane, scrying\n* 6th level (1 slot): eye bite\n\nFor casting these spells, each hag is a 12th-level spellcaster that uses Intelligence as her spellcasting ability. The spell save DC is 12+the hag''s Intelligence modifier, and the spell attack bonus is 4+the hag''s Intelligence modifier. Hag Eye (Coven Only). A hag coven can craft a magic item called a hag eye, which is made from a real eye coated in varnish and often fitted to a pendant or other wearable item. The hag eye is usually entrusted to a minion for safekeeping and transport. A hag in the coven can take an action to see what the hag eye sees if the hag eye is on the same plane of existence. A hag eye has AC 10, 1 hit point, and darkvision with a radius of 60 feet. If it is destroyed, each coven member takes 3d10 psychic damage and is blinded for 24 hours.\nA hag coven can have only one hag eye at a time, and creating a new one requires all three members of the coven to perform a ritual. The ritual takes 1 hour, and the hags can''t perform it while blinded. During the ritual, if the hags take any action other than performing the ritual, they must start over. Sentidos: darkvision 60 ft., passive Perception 14. Idiomas: Common, Draconic, Sylvan Dados de golpe: 11d8+33 Armadura: natural armor","actions":"Claws. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage. Illusory Appearance. The hag covers herself and anything she is wearing or carrying with a magical illusion that makes her look like another creature of her general size and humanoid shape. The illusion ends if the hag takes a bonus action to end it or if she dies.\nThe changes wrought by this effect fail to hold up to physical inspection. For example, the hag could appear to have smooth skin, but someone touching her would feel her rough flesh. Otherwise, a creature must take an action to visually inspect the illusion and succeed on a DC 20 Intelligence (Investigation) check to discern that the hag is disguised. Invisible Passage. The hag magically turns invisible until she attacks or casts a spell, or until her concentration ends (as if concentrating on a spell). While invisible, she leaves no physical evidence of her passage, so she can be tracked only by magic. Any equipment she wears or carries is invisible with her.","alignment":"Neutral maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Bugbear', 'Humanoide', 'Mediano', '16', '27', '1', '{"id":"srd-bugbear","name":"Bugbear","type":"Humanoide","size":"Mediano","ac":16,"hp":27,"speed":"30 pies","cr":1,"stats":{"str":15,"dex":14,"con":13,"int":8,"wis":11,"cha":9},"abilities":"Brute. A melee weapon deals one extra die of its damage when the bugbear hits with it (included in the attack). Surprise Attack. If the bugbear surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 7 (2d6) damage from the attack. Sentidos: darkvision 60 ft., passive Perception 10. Idiomas: Common, Goblin Dados de golpe: 5d8+5 Armadura: hide armor, shield","actions":"Morningstar. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 11 (2d8 + 2) piercing damage. Javelin. Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 9 (2d6 + 2) piercing damage in melee or 5 (1d6 + 2) piercing damage at range.","alignment":"Caótico maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Búho', 'Bestia', 'Diminuto', '11', '1', '0', '{"id":"srd-owl","name":"Búho","type":"Bestia","size":"Diminuto","ac":11,"hp":1,"speed":"5 pies, vuelo 60 pies","cr":0,"stats":{"str":3,"dex":13,"con":8,"int":2,"wis":12,"cha":7},"abilities":"Flyby. The owl doesn''t provoke opportunity attacks when it flies out of an enemy''s reach. Keen Hearing and Sight. The owl has advantage on Wisdom (Perception) checks that rely on hearing or sight. Sentidos: darkvision 120 ft., passive Perception 13 Dados de golpe: 1d4-1","actions":"Talons. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 1 slashing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Búho gigante', 'Bestia', 'Grande', '12', '19', '0.25', '{"id":"srd-giant-owl","name":"Búho gigante","type":"Bestia","size":"Grande","ac":12,"hp":19,"speed":"5 pies, vuelo 60 pies","cr":0.25,"stats":{"str":13,"dex":15,"con":12,"int":8,"wis":13,"cha":10},"abilities":"Flyby. The owl doesn''t provoke opportunity attacks when it flies out of an enemy''s reach. Keen Hearing and Sight. The owl has advantage on Wisdom (Perception) checks that rely on hearing or sight. Sentidos: darkvision 120 ft., passive Perception 15. Idiomas: Giant Owl, understands Common, Elvish, and Sylvan but can''t speak Dados de golpe: 3d10+3","actions":"Talons. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 8 (2d6 + 1) slashing damage.","alignment":"Neutral","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Búho-oso', 'Monstruosidad', 'Grande', '13', '59', '3', '{"id":"srd-owlbear","name":"Búho-oso","type":"Monstruosidad","size":"Grande","ac":13,"hp":59,"speed":"40 pies","cr":3,"stats":{"str":20,"dex":12,"con":17,"int":3,"wis":12,"cha":7},"abilities":"Keen Sight and Smell. The owlbear has advantage on Wisdom (Perception) checks that rely on sight or smell. Sentidos: darkvision 60 ft., passive Perception 13 Dados de golpe: 7d10+21 Armadura: natural armor","actions":"Multiattack. The owlbear makes two attacks: one with its beak and one with its claws. Beak. Melee Weapon Attack: +7 to hit, reach 5 ft., one creature. Hit: 10 (1d10 + 5) piercing damage. Claws. Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 14 (2d8 + 5) slashing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Buitre', 'Bestia', 'Mediano', '10', '5', '0', '{"id":"srd-vulture","name":"Buitre","type":"Bestia","size":"Mediano","ac":10,"hp":5,"speed":"10 pies, vuelo 50 pies","cr":0,"stats":{"str":7,"dex":10,"con":13,"int":2,"wis":12,"cha":4},"abilities":"Keen Sight and Smell. The vulture has advantage on Wisdom (Perception) checks that rely on sight or smell. Pack Tactics. The vulture has advantage on an attack roll against a creature if at least one of the vulture''s allies is within 5 ft. of the creature and the ally isn''t incapacitated. Sentidos: passive Perception 13 Dados de golpe: 1d8+1","actions":"Beak. Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) piercing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Buitre gigante', 'Bestia', 'Grande', '10', '22', '1', '{"id":"srd-giant-vulture","name":"Buitre gigante","type":"Bestia","size":"Grande","ac":10,"hp":22,"speed":"10 pies, vuelo 60 pies","cr":1,"stats":{"str":15,"dex":10,"con":15,"int":6,"wis":12,"cha":7},"abilities":"Keen Sight and Smell. The vulture has advantage on Wisdom (Perception) checks that rely on sight or smell. Pack Tactics. The vulture has advantage on an attack roll against a creature if at least one of the vulture''s allies is within 5 ft. of the creature and the ally isn''t incapacitated. Sentidos: passive Perception 13. Idiomas: understands Common but can''t speak Dados de golpe: 3d10+6","actions":"Multiattack. The vulture makes two attacks: one with its beak and one with its talons. Beak. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) piercing damage. Talons. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 9 (2d6 + 2) slashing damage.","alignment":"Neutral maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Bulette', 'Monstruosidad', 'Grande', '17', '94', '5', '{"id":"srd-bulette","name":"Bulette","type":"Monstruosidad","size":"Grande","ac":17,"hp":94,"speed":"40 pies, excavación 40 pies","cr":5,"stats":{"str":19,"dex":11,"con":21,"int":2,"wis":10,"cha":5},"abilities":"Standing Leap. The bulette''s long jump is up to 30 ft. and its high jump is up to 15 ft., with or without a running start. Sentidos: darkvision 60 ft., tremorsense 60 ft., passive Perception 16 Dados de golpe: 9d10+45 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 30 (4d12 + 4) piercing damage. Deadly Leap. If the bulette jumps at least 15 ft. as part of its movement, it can then use this action to land on its ft. in a space that contains one or more other creatures. Each of those creatures must succeed on a DC 16 Strength or Dexterity saving throw (target''s choice) or be knocked prone and take 14 (3d6 + 4) bludgeoning damage plus 14 (3d6 + 4) slashing damage. On a successful save, the creature takes only half the damage, isn''t knocked prone, and is pushed 5 ft. out of the bulette''s space into an unoccupied space of the creature''s choice. If no unoccupied space is within range, the creature instead falls prone in the bulette''s space.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Caballero', 'Humanoide', 'Mediano', '18', '52', '3', '{"id":"srd-knight","name":"Caballero","type":"Humanoide","size":"Mediano","ac":18,"hp":52,"speed":"30 pies","cr":3,"stats":{"str":16,"dex":11,"con":14,"int":11,"wis":11,"cha":15},"abilities":"Brave. The knight has advantage on saving throws against being frightened. Sentidos: passive Perception 10. Idiomas: any one language (usually Common) Dados de golpe: 8d8+16 Armadura: plate","actions":"Multiattack. The knight makes two melee attacks. Greatsword. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage. Heavy Crossbow. Ranged Weapon Attack: +2 to hit, range 100/400 ft., one target. Hit: 5 (1d10) piercing damage. Leadership (Recharges after a Short or Long Rest). For 1 minute, the knight can utter a special command or warning whenever a nonhostile creature that it can see within 30 ft. of it makes an attack roll or a saving throw. The creature can add a d4 to its roll provided it can hear and understand the knight. A creature can benefit from only one Leadership die at a time. This effect ends if the knight is incapacitated.","alignment":"Cualquiera","source":"srd-5.1"}'::jsonb, 'srd-5.1')
insert into public.srd_monsters (slug, name, type, size, ac, hp, cr, data, source)
values
  ('', 'Caballito de mar', 'Bestia', 'Diminuto', '11', '1', '0', '{"id":"srd-sea-horse","name":"Caballito de mar","type":"Bestia","size":"Diminuto","ac":11,"hp":1,"speed":"nado 20 pies","cr":0,"stats":{"str":1,"dex":12,"con":8,"int":1,"wis":10,"cha":2},"abilities":"Water Breathing. The sea horse can breathe only underwater. Sentidos: passive Perception 10 Dados de golpe: 1d4-1","actions":"","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Caballito de mar gigante', 'Bestia', 'Grande', '13', '16', '0.5', '{"id":"srd-giant-sea-horse","name":"Caballito de mar gigante","type":"Bestia","size":"Grande","ac":13,"hp":16,"speed":"0 pies, nado 40 pies","cr":0.5,"stats":{"str":12,"dex":15,"con":11,"int":2,"wis":12,"cha":5},"abilities":"Charge. If the sea horse moves at least 20 ft. straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 (2d6) bludgeoning damage. If the target is a creature, it must succeed on a DC 11 Strength saving throw or be knocked prone. Water Breathing. The sea horse can breathe only underwater. Sentidos: passive Perception 11 Dados de golpe: 3d10 Armadura: natural armor","actions":"Ram. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Caballo de montura', 'Bestia', 'Grande', '10', '13', '0.25', '{"id":"srd-riding-horse","name":"Caballo de montura","type":"Bestia","size":"Grande","ac":10,"hp":13,"speed":"60 pies","cr":0.25,"stats":{"str":16,"dex":10,"con":12,"int":2,"wis":11,"cha":7},"abilities":"Sentidos: passive Perception 10 Dados de golpe: 2d10+2","actions":"Hooves. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (2d4 + 3) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Caballo de tiro', 'Bestia', 'Grande', '10', '19', '0.25', '{"id":"srd-draft-horse","name":"Caballo de tiro","type":"Bestia","size":"Grande","ac":10,"hp":19,"speed":"40 pies","cr":0.25,"stats":{"str":18,"dex":10,"con":12,"int":2,"wis":11,"cha":7},"abilities":"Sentidos: passive Perception 10 Dados de golpe: 3d10+3","actions":"Hooves. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (2d4 + 4) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cabra', 'Bestia', 'Mediano', '10', '4', '0', '{"id":"srd-goat","name":"Cabra","type":"Bestia","size":"Mediano","ac":10,"hp":4,"speed":"40 pies","cr":0,"stats":{"str":12,"dex":10,"con":11,"int":2,"wis":10,"cha":5},"abilities":"Charge. If the goat moves at least 20 ft. straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 2 (1d4) bludgeoning damage. If the target is a creature, it must succeed on a DC 10 Strength saving throw or be knocked prone. Sure-Footed. The goat has advantage on Strength and Dexterity saving throws made against effects that would knock it prone. Sentidos: passive Perception 10 Dados de golpe: 1d8","actions":"Ram. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 1) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cabra gigante', 'Bestia', 'Grande', '11', '19', '0.5', '{"id":"srd-giant-goat","name":"Cabra gigante","type":"Bestia","size":"Grande","ac":11,"hp":19,"speed":"40 pies","cr":0.5,"stats":{"str":17,"dex":11,"con":12,"int":3,"wis":12,"cha":6},"abilities":"Charge. If the goat moves at least 20 ft. straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 5 (2d4) bludgeoning damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone. Sure-Footed. The goat has advantage on Strength and Dexterity saving throws made against effects that would knock it prone. Sentidos: passive Perception 11 Dados de golpe: 3d10+3 Armadura: natural armor","actions":"Ram. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (2d4 + 3) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Camello', 'Bestia', 'Grande', '9', '15', '0.125', '{"id":"srd-camel","name":"Camello","type":"Bestia","size":"Grande","ac":9,"hp":15,"speed":"50 pies","cr":0.125,"stats":{"str":16,"dex":8,"con":14,"int":2,"wis":8,"cha":5},"abilities":"Sentidos: passive Perception 9 Dados de golpe: 2d10+4","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Can del infierno', 'Demonio', 'Mediano', '15', '45', '3', '{"id":"srd-hell-hound","name":"Can del infierno","type":"Demonio","size":"Mediano","ac":15,"hp":45,"speed":"50 pies","cr":3,"stats":{"str":17,"dex":12,"con":14,"int":6,"wis":13,"cha":6},"abilities":"Keen Hearing and Smell. The hound has advantage on Wisdom (Perception) checks that rely on hearing or smell. Pack Tactics. The hound has advantage on an attack roll against a creature if at least one of the hound''s allies is within 5 ft. of the creature and the ally isn''t incapacitated. Sentidos: darkvision 60 ft., passive Perception 15. Idiomas: understands Infernal but can''t speak it Dados de golpe: 7d8+14 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) piercing damage plus 7 (2d6) fire damage. Fire Breath (Recharge 5-6). The hound exhales fire in a 15-foot cone. Each creature in that area must make a DC 12 Dexterity saving throw, taking 21 (6d6) fire damage on a failed save, or half as much damage on a successful one.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cangrejo', 'Bestia', 'Diminuto', '11', '2', '0', '{"id":"srd-crab","name":"Cangrejo","type":"Bestia","size":"Diminuto","ac":11,"hp":2,"speed":"20 pies, nado 20 pies","cr":0,"stats":{"str":2,"dex":11,"con":10,"int":1,"wis":8,"cha":2},"abilities":"Amphibious. The crab can breathe air and water. Sentidos: blindsight 30 ft., passive Perception 9 Dados de golpe: 1d4 Armadura: natural armor","actions":"Claw. Melee Weapon Attack: +0 to hit, reach 5 ft., one target. Hit: 1 bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cangrejo gigante', 'Bestia', 'Mediano', '15', '13', '0.125', '{"id":"srd-giant-crab","name":"Cangrejo gigante","type":"Bestia","size":"Mediano","ac":15,"hp":13,"speed":"30 pies, nado 30 pies","cr":0.125,"stats":{"str":13,"dex":15,"con":11,"int":1,"wis":9,"cha":3},"abilities":"Amphibious. The crab can breathe air and water. Sentidos: blindsight 30 ft., passive Perception 9 Dados de golpe: 3d8 Armadura: natural armor","actions":"Claw. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) bludgeoning damage, and the target is grappled (escape DC 11). The crab has two claws, each of which can grapple only one target.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Capitán bandido', 'Humanoide', 'Mediano', '15', '65', '2', '{"id":"srd-bandit-captain","name":"Capitán bandido","type":"Humanoide","size":"Mediano","ac":15,"hp":65,"speed":"30 pies","cr":2,"stats":{"str":15,"dex":16,"con":14,"int":14,"wis":11,"cha":14},"abilities":"Sentidos: passive Perception 10. Idiomas: any two languages Dados de golpe: 10d8+20 Armadura: studded leather","actions":"Multiattack. The captain makes three melee attacks: two with its scimitar and one with its dagger. Or the captain makes two ranged attacks with its daggers. Scimitar. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage. Dagger. Melee or Ranged Weapon Attack: +5 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 5 (1d4 + 3) piercing damage.","alignment":"Cualquiera no legal","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Centauro', 'Monstruosidad', 'Grande', '12', '45', '2', '{"id":"srd-centaur","name":"Centauro","type":"Monstruosidad","size":"Grande","ac":12,"hp":45,"speed":"50 pies","cr":2,"stats":{"str":18,"dex":14,"con":14,"int":9,"wis":13,"cha":11},"abilities":"Charge. If the centaur moves at least 30 ft. straight toward a target and then hits it with a pike attack on the same turn, the target takes an extra 10 (3d6) piercing damage. Sentidos: passive Perception 13. Idiomas: Elvish, Sylvan Dados de golpe: 6d10+12","actions":"Multiattack. The centaur makes two attacks: one with its pike and one with its hooves or two with its longbow. Pike. Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 9 (1d10 + 4) piercing damage. Hooves. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage. Longbow. Ranged Weapon Attack: +4 to hit, range 150/600 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","alignment":"Neutral bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Chacal', 'Bestia', 'Pequeño', '12', '3', '0', '{"id":"srd-jackal","name":"Chacal","type":"Bestia","size":"Pequeño","ac":12,"hp":3,"speed":"40 pies","cr":0,"stats":{"str":8,"dex":15,"con":11,"int":3,"wis":12,"cha":6},"abilities":"Keen Hearing and Smell. The jackal has advantage on Wisdom (Perception) checks that rely on hearing or smell. Pack Tactics. The jackal has advantage on an attack roll against a creature if at least one of the jackal''s allies is within 5 ft. of the creature and the ally isn''t incapacitated. Sentidos: passive Perception 13 Dados de golpe: 1d6","actions":"Bite. Melee Weapon Attack: +1 to hit, reach 5 ft., one target. Hit: 1 (1d4 - 1) piercing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Chuul', 'Aberración', 'Grande', '16', '93', '4', '{"id":"srd-chuul","name":"Chuul","type":"Aberración","size":"Grande","ac":16,"hp":93,"speed":"30 pies, nado 30 pies","cr":4,"stats":{"str":19,"dex":10,"con":16,"int":5,"wis":11,"cha":5},"abilities":"Amphibious. The chuul can breathe air and water. Sense Magic. The chuul senses magic within 120 feet of it at will. This trait otherwise works like the detect magic spell but isn''t itself magical. Sentidos: darkvision 60 ft., passive Perception 14. Idiomas: understands Deep Speech but can''t speak Dados de golpe: 11d10+33 Armadura: natural armor","actions":"Multiattack. The chuul makes two pincer attacks. If the chuul is grappling a creature, the chuul can also use its tentacles once. Pincer. Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage. The target is grappled (escape DC 14) if it is a Large or smaller creature and the chuul doesn''t have two other creatures grappled. Tentacles. One creature grappled by the chuul must succeed on a DC 13 Constitution saving throw or be poisoned for 1 minute. Until this poison ends, the target is paralyzed. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","alignment":"Caótico maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Ciempiés gigante', 'Bestia', 'Pequeño', '13', '4', '0.25', '{"id":"srd-giant-centipede","name":"Ciempiés gigante","type":"Bestia","size":"Pequeño","ac":13,"hp":4,"speed":"30 pies, escalada 30 pies","cr":0.25,"stats":{"str":5,"dex":14,"con":12,"int":1,"wis":7,"cha":3},"abilities":"Sentidos: blindsight 30 ft., passive Perception 8 Dados de golpe: 1d6+1 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) piercing damage, and the target must succeed on a DC 11 Constitution saving throw or take 10 (3d6) poison damage. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Ciervo', 'Bestia', 'Mediano', '13', '4', '0', '{"id":"srd-deer","name":"Ciervo","type":"Bestia","size":"Mediano","ac":13,"hp":4,"speed":"50 pies","cr":0,"stats":{"str":11,"dex":16,"con":11,"int":2,"wis":14,"cha":5},"abilities":"Sentidos: passive Perception 12 Dados de golpe: 1d8","actions":"Bite. Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) piercing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cloaker', 'Aberración', 'Grande', '14', '78', '8', '{"id":"srd-cloaker","name":"Cloaker","type":"Aberración","size":"Grande","ac":14,"hp":78,"speed":"10 pies, vuelo 40 pies","cr":8,"stats":{"str":17,"dex":15,"con":12,"int":13,"wis":12,"cha":14},"abilities":"Damage Transfer. While attached to a creature, the cloaker takes only half the damage dealt to it (rounded down). and that creature takes the other half. False Appearance. While the cloaker remains motionless without its underside exposed, it is indistinguishable from a dark leather cloak. Light Sensitivity. While in bright light, the cloaker has disadvantage on attack rolls and Wisdom (Perception) checks that rely on sight. Sentidos: darkvision 60 ft., passive Perception 11. Idiomas: Deep Speech, Undercommon Dados de golpe: 12d10+12 Armadura: natural armor","actions":"Multiattack. The cloaker makes two attacks: one with its bite and one with its tail. Bite. Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 10 (2d6 + 3) piercing damage, and if the target is Large or smaller, the cloaker attaches to it. If the cloaker has advantage against the target, the cloaker attaches to the target''s head, and the target is blinded and unable to breathe while the cloaker is attached. While attached, the cloaker can make this attack only against the target and has advantage on the attack roll. The cloaker can detach itself by spending 5 feet of its movement. A creature, including the target, can take its action to detach the cloaker by succeeding on a DC 16 Strength check. Tail. Melee Weapon Attack: +6 to hit, reach 10 ft., one creature. Hit: 7 (1d8 + 3) slashing damage. Moan. Each creature within 60 feet of the cloaker that can hear its moan and that isn''t an aberration must succeed on a DC 13 Wisdom saving throw or become frightened until the end of the cloaker''s next turn. If a creature''s saving throw is successful, the creature is immune to the cloaker''s moan for the next 24 hours. Phantasms (Recharges after a Short or Long Rest). The cloaker magically creates three illusory duplicates of itself if it isn''t in bright light. The duplicates move with it and mimic its actions, shifting position so as to make it impossible to track which cloaker is the real one. If the cloaker is ever in an area of bright light, the duplicates disappear.\nWhenever any creature targets the cloaker with an attack or a harmful spell while a duplicate remains, that creature rolls randomly to determine whether it targets the cloaker or one of the duplicates. A creature is unaffected by this magical effect if it can''t see or if it relies on senses other than sight.\nA duplicate has the cloaker''s AC and uses its saving throws. If an attack hits a duplicate, or if a duplicate fails a saving throw against an effect that deals damage, the duplicate disappears.","alignment":"Caótico neutral","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cockatrice', 'Monstruosidad', 'Pequeño', '11', '27', '0.5', '{"id":"srd-cockatrice","name":"Cockatrice","type":"Monstruosidad","size":"Pequeño","ac":11,"hp":27,"speed":"20 pies, vuelo 40 pies","cr":0.5,"stats":{"str":6,"dex":12,"con":12,"int":2,"wis":13,"cha":5},"abilities":"Sentidos: darkvision 60 ft., passive Perception 11 Dados de golpe: 6d6+6","actions":"Bite. Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 3 (1d4 + 1) piercing damage, and the target must succeed on a DC 11 Constitution saving throw against being magically petrified. On a failed save, the creature begins to turn to stone and is restrained. It must repeat the saving throw at the end of its next turn. On a success, the effect ends. On a failure, the creature is petrified for 24 hours.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cocodrilo', 'Bestia', 'Grande', '12', '19', '0.5', '{"id":"srd-crocodile","name":"Cocodrilo","type":"Bestia","size":"Grande","ac":12,"hp":19,"speed":"20 pies, nado 20 pies","cr":0.5,"stats":{"str":15,"dex":10,"con":13,"int":2,"wis":10,"cha":5},"abilities":"Hold Breath. The crocodile can hold its breath for 15 minutes. Sentidos: passive Perception 10 Dados de golpe: 3d10+3 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 7 (1d10 + 2) piercing damage, and the target is grappled (escape DC 12). Until this grapple ends, the target is restrained, and the crocodile can''t bite another target.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cocodrilo gigante', 'Bestia', 'Enorme', '14', '85', '5', '{"id":"srd-giant-crocodile","name":"Cocodrilo gigante","type":"Bestia","size":"Enorme","ac":14,"hp":85,"speed":"30 pies, nado 50 pies","cr":5,"stats":{"str":21,"dex":9,"con":17,"int":2,"wis":10,"cha":7},"abilities":"Hold Breath. The crocodile can hold its breath for 30 minutes. Sentidos: passive Perception 10 Dados de golpe: 9d12+27 Armadura: natural armor","actions":"Multiattack. The crocodile makes two attacks: one with its bite and one with its tail. Bite. Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 21 (3d10 + 5) piercing damage, and the target is grappled (escape DC 16). Until this grapple ends, the target is restrained, and the crocodile can''t bite another target. Tail. Melee Weapon Attack: +8 to hit, reach 10 ft., one target not grappled by the crocodile. Hit: 14 (2d8 + 5) bludgeoning damage. If the target is a creature, it must succeed on a DC 16 Strength saving throw or be knocked prone.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Comadreja', 'Bestia', 'Diminuto', '13', '1', '0', '{"id":"srd-weasel","name":"Comadreja","type":"Bestia","size":"Diminuto","ac":13,"hp":1,"speed":"30 pies","cr":0,"stats":{"str":3,"dex":16,"con":8,"int":2,"wis":12,"cha":3},"abilities":"Keen Hearing and Smell. The weasel has advantage on Wisdom (Perception) checks that rely on hearing or smell. Sentidos: passive Perception 13 Dados de golpe: 1d4-1","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 1 piercing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Comadreja gigante', 'Bestia', 'Mediano', '13', '9', '0.125', '{"id":"srd-giant-weasel","name":"Comadreja gigante","type":"Bestia","size":"Mediano","ac":13,"hp":9,"speed":"40 pies","cr":0.125,"stats":{"str":11,"dex":16,"con":10,"int":4,"wis":12,"cha":5},"abilities":"Keen Hearing and Smell. The weasel has advantage on Wisdom (Perception) checks that rely on hearing or smell. Sentidos: darkvision 60 ft., passive Perception 13 Dados de golpe: 2d8","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Corcel de guerra', 'Bestia', 'Grande', '11', '19', '0.5', '{"id":"srd-warhorse","name":"Corcel de guerra","type":"Bestia","size":"Grande","ac":11,"hp":19,"speed":"60 pies","cr":0.5,"stats":{"str":18,"dex":12,"con":13,"int":2,"wis":12,"cha":7},"abilities":"Trampling Charge. If the horse moves at least 20 ft. straight toward a creature and then hits it with a hooves attack on the same turn, that target must succeed on a DC 14 Strength saving throw or be knocked prone. If the target is prone, the horse can make another attack with its hooves against it as a bonus action. Sentidos: passive Perception 11 Dados de golpe: 3d10+3","actions":"Hooves. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Couatl', 'Celestial', 'Mediano', '19', '97', '4', '{"id":"srd-couatl","name":"Couatl","type":"Celestial","size":"Mediano","ac":19,"hp":97,"speed":"30 pies, vuelo 90 pies","cr":4,"stats":{"str":16,"dex":20,"con":17,"int":18,"wis":20,"cha":18},"abilities":"Innate Spellcasting. The couatl''s spellcasting ability is Charisma (spell save DC 14). It can innately cast the following spells, requiring only verbal components:\n\nAt will: detect evil and good, detect magic, detect thoughts\n3/day each: bless, create food and water, cure wounds, lesser restoration, protection from poison, sanctuary, shield\n1/day each: dream, greater restoration, scrying Magic Weapons. The couatl''s weapon attacks are magical. Shielded Mind. The couatl is immune to scrying and to any effect that would sense its emotions, read its thoughts, or detect its location. Sentidos: truesight 120 ft., passive Perception 15. Idiomas: all, telepathy 120 ft. Dados de golpe: 13d8+39 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +8 to hit, reach 5 ft., one creature. Hit: 8 (1d6 + 5) piercing damage, and the target must succeed on a DC 13 Constitution saving throw or be poisoned for 24 hours. Until this poison ends, the target is unconscious. Another creature can use an action to shake the target awake. Constrict. Melee Weapon Attack: +6 to hit, reach 10 ft., one Medium or smaller creature. Hit: 10 (2d6 + 3) bludgeoning damage, and the target is grappled (escape DC 15). Until this grapple ends, the target is restrained, and the couatl can''t constrict another target. Change Shape. The couatl magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the couatl''s choice).\nIn a new form, the couatl retains its game statistics and ability to speak, but its AC, movement modes, Strength, Dexterity, and other actions are replaced by those of the new form, and it gains any statistics and capabilities (except class features, legendary actions, and lair actions) that the new form has but that it lacks. If the new form has a bite attack, the couatl can use its bite in that form.","alignment":"Legal bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón azul', 'Dragón', 'Mediano', '17', '52', '3', '{"id":"srd-blue-dragon-wyrmling","name":"Cría de dragón azul","type":"Dragón","size":"Mediano","ac":17,"hp":52,"speed":"30 pies, vuelo 60 pies, excavación 15 pies","cr":3,"stats":{"str":17,"dex":10,"con":15,"int":12,"wis":11,"cha":15},"abilities":"Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 8d8+16 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d10 + 3) piercing damage plus 3 (1d6) lightning damage. Lightning Breath (Recharge 5-6). The dragon exhales lightning in a 30-foot line that is 5 feet wide. Each creature in that line must make a DC 12 Dexterity saving throw, taking 22 (4d10) lightning damage on a failed save, or half as much damage on a successful one.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón blanco', 'Dragón', 'Mediano', '16', '32', '2', '{"id":"srd-white-dragon-wyrmling","name":"Cría de dragón blanco","type":"Dragón","size":"Mediano","ac":16,"hp":32,"speed":"30 pies, vuelo 60 pies, nado 30 pies, excavación 15 pies","cr":2,"stats":{"str":14,"dex":10,"con":14,"int":5,"wis":10,"cha":11},"abilities":"Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 5d8+10 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 2 (1d4) cold damage. Cold Breath (Recharge 5-6). The dragon exhales an icy blast of hail in a 15-foot cone. Each creature in that area must make a DC 12 Constitution saving throw, taking 22 (5d8) cold damage on a failed save, or half as much damage on a successful one.","alignment":"Caótico maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón de bronce', 'Dragón', 'Mediano', '17', '32', '2', '{"id":"srd-bronze-dragon-wyrmling","name":"Cría de dragón de bronce","type":"Dragón","size":"Mediano","ac":17,"hp":32,"speed":"30 pies, vuelo 60 pies, nado 30 pies","cr":2,"stats":{"str":17,"dex":10,"con":15,"int":12,"wis":11,"cha":15},"abilities":"Amphibious. The dragon can breathe air and water. Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 5d8+10 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d10 + 3) piercing damage. Breath Weapons (Recharge 5-6). The dragon uses one of the following breath weapons.\n**Lightning Breath.** The dragon exhales lightning in a 40-foot line that is 5 feet wide. Each creature in that line must make a DC 12 Dexterity saving throw, taking 16 (3d10) lightning damage on a failed save, or half as much damage on a successful one.\n**Repulsion Breath.** The dragon exhales repulsion energy in a 30-foot cone. Each creature in that area must succeed on a DC 12 Strength saving throw. On a failed save, the creature is pushed 30 feet away from the dragon.","alignment":"Legal bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón de cobre', 'Dragón', 'Mediano', '16', '22', '1', '{"id":"srd-copper-dragon-wyrmling","name":"Cría de dragón de cobre","type":"Dragón","size":"Mediano","ac":16,"hp":22,"speed":"30 pies, vuelo 60 pies, escalada 30 pies","cr":1,"stats":{"str":15,"dex":12,"con":13,"int":14,"wis":11,"cha":13},"abilities":"Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 4d8+4 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage. Breath Weapons (Recharge 5-6). The dragon uses one of the following breath weapons.\n**Acid Breath.** The dragon exhales acid in an 20-foot line that is 5 feet wide. Each creature in that line must make a DC 11 Dexterity saving throw, taking 18 (4d8) acid damage on a failed save, or half as much damage on a successful one.\n**Slowing Breath.** The dragon exhales gas in a 1 5-foot cone. Each creature in that area must succeed on a DC 11 Constitution saving throw. On a failed save, the creature can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the creature can use either an action or a bonus action on its turn, but not both. These effects last for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself with a successful save.","alignment":"Caótico bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón de latón', 'Dragón', 'Mediano', '16', '16', '1', '{"id":"srd-brass-dragon-wyrmling","name":"Cría de dragón de latón","type":"Dragón","size":"Mediano","ac":16,"hp":16,"speed":"30 pies, vuelo 60 pies, excavación 15 pies","cr":1,"stats":{"str":15,"dex":10,"con":13,"int":10,"wis":11,"cha":13},"abilities":"Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 3d8+3 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage. Breath Weapons (Recharge 5-6). The dragon uses one of the following breath weapons.\n**Fire Breath.** The dragon exhales fire in an 20-foot line that is 5 feet wide. Each creature in that line must make a DC 11 Dexterity saving throw, taking 14 (4d6) fire damage on a failed save, or half as much damage on a successful one.\n**Sleep Breath.** The dragon exhales sleep gas in a 15-foot cone. Each creature in that area must succeed on a DC 11 Constitution saving throw or fall unconscious for 1 minute. This effect ends for a creature if the creature takes damage or someone uses an action to wake it.","alignment":"Caótico bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón dorado', 'Dragón', 'Mediano', '17', '60', '3', '{"id":"srd-gold-dragon-wyrmling","name":"Cría de dragón dorado","type":"Dragón","size":"Mediano","ac":17,"hp":60,"speed":"30 pies, vuelo 60 pies, nado 30 pies","cr":3,"stats":{"str":19,"dex":14,"con":17,"int":14,"wis":11,"cha":16},"abilities":"Amphibious. The dragon can breathe air and water. Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 8d8+24 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (1d10 + 4) piercing damage. Breath Weapons (Recharge 5-6). The dragon uses one of the following breath weapons.\n**Fire Breath.** The dragon exhales fire in a 15-foot cone. Each creature in that area must make a DC 13 Dexterity saving throw, taking 22 (4d10) fire damage on a failed save, or half as much damage on a successful one.\n**Weakening Breath.** The dragon exhales gas in a 15-foot cone. Each creature in that area must succeed on a DC 13 Strength saving throw or have disadvantage on Strength-based attack rolls, Strength checks, and Strength saving throws for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","alignment":"Legal bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón negro', 'Dragón', 'Mediano', '17', '33', '2', '{"id":"srd-black-dragon-wyrmling","name":"Cría de dragón negro","type":"Dragón","size":"Mediano","ac":17,"hp":33,"speed":"30 pies, vuelo 60 pies, nado 30 pies","cr":2,"stats":{"str":15,"dex":14,"con":13,"int":10,"wis":11,"cha":13},"abilities":"Amphibious. The dragon can breathe air and water. Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 6d8+6 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 2 (1d4) acid damage. Acid Breath (Recharge 5-6). The dragon exhales acid in a 15-foot line that is 5 feet wide. Each creature in that line must make a DC 11 Dexterity saving throw, taking 22 (5d8) acid damage on a failed save, or half as much damage on a successful one.","alignment":"Caótico maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón plateado', 'Dragón', 'Mediano', '17', '45', '2', '{"id":"srd-silver-dragon-wyrmling","name":"Cría de dragón plateado","type":"Dragón","size":"Mediano","ac":17,"hp":45,"speed":"30 pies, vuelo 60 pies","cr":2,"stats":{"str":19,"dex":10,"con":17,"int":12,"wis":11,"cha":15},"abilities":"Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 6d8+18 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (1d10 + 4) piercing damage. Breath Weapons (Recharge 5-6). The dragon uses one of the following breath weapons.\n**Cold Breath.** The dragon exhales an icy blast in a 15-foot cone. Each creature in that area must make a DC 13 Constitution saving throw, taking 18 (4d8) cold damage on a failed save, or half as much damage on a successful one.\n**Paralyzing Breath.** The dragon exhales paralyzing gas in a 15-foot cone. Each creature in that area must succeed on a DC 13 Constitution saving throw or be paralyzed for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","alignment":"Legal bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón rojo', 'Dragón', 'Mediano', '17', '75', '4', '{"id":"srd-red-dragon-wyrmling","name":"Cría de dragón rojo","type":"Dragón","size":"Mediano","ac":17,"hp":75,"speed":"30 pies, vuelo 60 pies, escalada 30 pies","cr":4,"stats":{"str":19,"dex":10,"con":17,"int":12,"wis":11,"cha":15},"abilities":"Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 10d8+30 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (1d10 + 4) piercing damage plus 3 (1d6) fire damage. Fire Breath (Recharge 5-6). The dragon exhales fire in a 15-foot cone. Each creature in that area must make a DC 13 Dexterity saving throw, taking 24 (7d6) fire damage on a failed save, or half as much damage on a successful one.","alignment":"Caótico maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cría de dragón verde', 'Dragón', 'Mediano', '17', '38', '2', '{"id":"srd-green-dragon-wyrmling","name":"Cría de dragón verde","type":"Dragón","size":"Mediano","ac":17,"hp":38,"speed":"30 pies, vuelo 60 pies, nado 30 pies","cr":2,"stats":{"str":15,"dex":12,"con":13,"int":14,"wis":11,"cha":13},"abilities":"Amphibious. The dragon can breathe air and water. Sentidos: blindsight 10 ft., darkvision 60 ft., passive Perception 14. Idiomas: Draconic Dados de golpe: 7d8+7 Armadura: natural armor","actions":"Bite. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 3 (1d6) poison damage. Poison Breath (Recharge 5-6). The dragon exhales poisonous gas in a 15-foot cone. Each creature in that area must make a DC 11 Constitution saving throw, taking 21 (6d6) poison damage on a failed save, or half as much damage on a successful one.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cubo gelatinoso', 'Limo', 'Grande', '6', '84', '2', '{"id":"srd-gelatinous-cube","name":"Cubo gelatinoso","type":"Limo","size":"Grande","ac":6,"hp":84,"speed":"15 pies","cr":2,"stats":{"str":14,"dex":3,"con":20,"int":1,"wis":6,"cha":1},"abilities":"Ooze Cube. The cube takes up its entire space. Other creatures can enter the space, but a creature that does so is subjected to the cube''s Engulf and has disadvantage on the saving throw.\nCreatures inside the cube can be seen but have total cover.\nA creature within 5 feet of the cube can take an action to pull a creature or object out of the cube. Doing so requires a successful DC 12 Strength check, and the creature making the attempt takes 10 (3d6) acid damage.\nThe cube can hold only one Large creature or up to four Medium or smaller creatures inside it at a time. Transparent. Even when the cube is in plain sight, it takes a successful DC 15 Wisdom (Perception) check to spot a cube that has neither moved nor attacked. A creature that tries to enter the cube''s space while unaware of the cube is surprised by the cube. Sentidos: blindsight 60 ft. (blind beyond this radius), passive Perception 8 Dados de golpe: 8d10+40","actions":"Pseudopod. Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 10 (3d6) acid damage. Engulf. The cube moves up to its speed. While doing so, it can enter Large or smaller creatures'' spaces. Whenever the cube enters a creature''s space, the creature must make a DC 12 Dexterity saving throw.\nOn a successful save, the creature can choose to be pushed 5 feet back or to the side of the cube. A creature that chooses not to be pushed suffers the consequences of a failed saving throw.\nOn a failed save, the cube enters the creature''s space, and the creature takes 10 (3d6) acid damage and is engulfed. The engulfed creature can''t breathe, is restrained, and takes 21 (6d6) acid damage at the start of each of the cube''s turns. When the cube moves, the engulfed creature moves with it.\nAn engulfed creature can try to escape by taking an action to make a DC 12 Strength check. On a success, the creature escapes and enters a space of its choice within 5 feet of the cube.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cuervo', 'Bestia', 'Diminuto', '12', '1', '0', '{"id":"srd-raven","name":"Cuervo","type":"Bestia","size":"Diminuto","ac":12,"hp":1,"speed":"10 pies, vuelo 50 pies","cr":0,"stats":{"str":2,"dex":14,"con":8,"int":2,"wis":12,"cha":6},"abilities":"Mimicry. The raven can mimic simple sounds it has heard, such as a person whispering, a baby crying, or an animal chittering. A creature that hears the sounds can tell they are imitations with a successful DC 10 Wisdom (Insight) check. Sentidos: passive Perception 13 Dados de golpe: 1d4-1","actions":"Beak. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 1 piercing damage.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Cultista', 'Humanoide', 'Mediano', '12', '9', '0.125', '{"id":"srd-cultist","name":"Cultista","type":"Humanoide","size":"Mediano","ac":12,"hp":9,"speed":"30 pies","cr":0.125,"stats":{"str":11,"dex":12,"con":10,"int":10,"wis":11,"cha":10},"abilities":"Dark Devotion. The cultist has advantage on saving throws against being charmed or frightened. Sentidos: passive Perception 10. Idiomas: any one language (usually Common) Dados de golpe: 2d8 Armadura: leather armor","actions":"Scimitar. Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 4 (1d6 + 1) slashing damage.","alignment":"Cualquiera no bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Darkmantle', 'Monstruosidad', 'Pequeño', '11', '22', '0.5', '{"id":"srd-darkmantle","name":"Darkmantle","type":"Monstruosidad","size":"Pequeño","ac":11,"hp":22,"speed":"10 pies, vuelo 30 pies","cr":0.5,"stats":{"str":16,"dex":12,"con":13,"int":2,"wis":10,"cha":5},"abilities":"Echolocation. The darkmantle can''t use its blindsight while deafened. False Appearance. While the darkmantle remains motionless, it is indistinguishable from a cave formation such as a stalactite or stalagmite. Sentidos: blindsight 60 ft., passive Perception 10 Dados de golpe: 5d6+5","actions":"Crush. Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 6 (1d6 + 3) bludgeoning damage, and the darkmantle attaches to the target. If the target is Medium or smaller and the darkmantle has advantage on the attack roll, it attaches by engulfing the target''s head, and the target is also blinded and unable to breathe while the darkmantle is attached in this way.\nWhile attached to the target, the darkmantle can attack no other creature except the target but has advantage on its attack rolls. The darkmantle''s speed also becomes 0, it can''t benefit from any bonus to its speed, and it moves with the target.\nA creature can detach the darkmantle by making a successful DC 13 Strength check as an action. On its turn, the darkmantle can detach itself from the target by using 5 feet of movement. Darkness Aura (1/day). A 15-foot radius of magical darkness extends out from the darkmantle, moves with it, and spreads around corners. The darkness lasts as long as the darkmantle maintains concentration, up to 10 minutes (as if concentrating on a spell). Darkvision can''t penetrate this darkness, and no natural light can illuminate it. If any of the darkness overlaps with an area of light created by a spell of 2nd level or lower, the spell creating the light is dispelled.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Deva', 'Celestial', 'Mediano', '17', '136', '10', '{"id":"srd-deva","name":"Deva","type":"Celestial","size":"Mediano","ac":17,"hp":136,"speed":"30 pies, vuelo 90 pies","cr":10,"stats":{"str":18,"dex":18,"con":18,"int":17,"wis":20,"cha":20},"abilities":"Angelic Weapons. The deva''s weapon attacks are magical. When the deva hits with any weapon, the weapon deals an extra 4d8 radiant damage (included in the attack). Innate Spellcasting. The deva''s spellcasting ability is Charisma (spell save DC 17). The deva can innately cast the following spells, requiring only verbal components:\nAt will: detect evil and good\n1/day each: commune, raise dead Magic Resistance. The deva has advantage on saving throws against spells and other magical effects. Sentidos: darkvision 120 ft., passive Perception 19. Idiomas: all, telepathy 120 ft. Dados de golpe: 16d8+64 Armadura: natural armor","actions":"Multiattack. The deva makes two melee attacks. Mace. Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) bludgeoning damage plus 18 (4d8) radiant damage. Healing Touch (3/Day). The deva touches another creature. The target magically regains 20 (4d8 + 2) hit points and is freed from any curse, disease, poison, blindness, or deafness. Change Shape. The deva magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the deva''s choice).\nIn a new form, the deva retains its game statistics and ability to speak, but its AC, movement modes, Strength, Dexterity, and special senses are replaced by those of the new form, and it gains any statistics and capabilities (except class features, legendary actions, and lair actions) that the new form has but that it lacks.","alignment":"Legal bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Diablillo', 'Demonio', 'Diminuto', '13', '10', '1', '{"id":"srd-imp","name":"Diablillo","type":"Demonio","size":"Diminuto","ac":13,"hp":10,"speed":"20 pies, vuelo 40 pies","cr":1,"stats":{"str":6,"dex":17,"con":13,"int":11,"wis":12,"cha":14},"abilities":"Shapechanger. The imp can use its action to polymorph into a beast form that resembles a rat (speed 20 ft.), a raven (20 ft., fly 60 ft.), or a spider (20 ft., climb 20 ft.), or back into its true form. Its statistics are the same in each form, except for the speed changes noted. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies. Devil''s Sight. Magical darkness doesn''t impede the imp''s darkvision. Magic Resistance. The imp has advantage on saving throws against spells and other magical effects. Variant: Familiar. The imp can serve another creature as a familiar, forming a telepathic bond with its willing master. While the two are bonded, the master can sense what the imp senses as long as they are within 1 mile of each other. While the imp is within 10 feet of its master, the master shares the imp''s Magic Resistance trait. At any time and for any reason, the imp can end its service as a familiar, ending the telepathic bond. Sentidos: darkvision 120 ft., passive Perception 11. Idiomas: Infernal, Common Dados de golpe: 3d4+3","actions":"Sting (Bite in Beast Form). Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage, and the target must make on a DC 11 Constitution saving throw, taking 10 (3d6) poison damage on a failed save, or half as much damage on a successful one. Invisibility. The imp magically turns invisible until it attacks, or until its concentration ends (as if concentrating on a spell). Any equipment the imp wears or carries is invisible with it.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1')
insert into public.srd_monsters (slug, name, type, size, ac, hp, cr, data, source)
values
  ('', 'Diablo barbado', 'Demonio', 'Mediano', '15', '110', '5', '{"id":"srd-barbed-devil","name":"Diablo barbado","type":"Demonio","size":"Mediano","ac":15,"hp":110,"speed":"30 pies","cr":5,"stats":{"str":16,"dex":17,"con":18,"int":12,"wis":14,"cha":14},"abilities":"Barbed Hide. At the start of each of its turns, the barbed devil deals 5 (1d10) piercing damage to any creature grappling it. Devil''s Sight. Magical darkness doesn''t impede the devil''s darkvision. Magic Resistance. The devil has advantage on saving throws against spells and other magical effects. Sentidos: darkvision 120 ft., passive Perception 18. Idiomas: Infernal, telepathy 120 ft. Dados de golpe: 13d8+52 Armadura: natural armor","actions":"Multiattack. The devil makes three melee attacks: one with its tail and two with its claws. Alternatively, it can use Hurl Flame twice. Claw. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage. Tail. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage. Hurl Flame. Ranged Spell Attack: +5 to hit, range 150 ft., one target. Hit: 10 (3d6) fire damage. If the target is a flammable object that isn''t being worn or carried, it also catches fire.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Diablo barbudo', 'Demonio', 'Mediano', '13', '52', '3', '{"id":"srd-bearded-devil","name":"Diablo barbudo","type":"Demonio","size":"Mediano","ac":13,"hp":52,"speed":"30 pies","cr":3,"stats":{"str":16,"dex":15,"con":15,"int":9,"wis":11,"cha":11},"abilities":"Devil''s Sight. Magical darkness doesn''t impede the devil''s darkvision. Magic Resistance. The devil has advantage on saving throws against spells and other magical effects. Steadfast. The devil can''t be frightened while it can see an allied creature within 30 feet of it. Sentidos: darkvision 120 ft., passive Perception 10. Idiomas: Infernal, telepathy 120 ft. Dados de golpe: 8d8+16 Armadura: natural armor","actions":"Multiattack. The devil makes two attacks: one with its beard and one with its glaive. Beard. Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 6 (1d8 + 2) piercing damage, and the target must succeed on a DC 12 Constitution saving throw or be poisoned for 1 minute. While poisoned in this way, the target can''t regain hit points. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. Glaive. Melee Weapon Attack: +5 to hit, reach 10 ft., one target. Hit: 8 (1d10 + 3) slashing damage. If the target is a creature other than an undead or a construct, it must succeed on a DC 12 Constitution saving throw or lose 5 (1d10) hit points at the start of each of its turns due to an infernal wound. Each time the devil hits the wounded target with this attack, the damage dealt by the wound increases by 5 (1d10). Any creature can take an action to stanch the wound with a successful DC 12 Wisdom (Medicine) check. The wound also closes if the target receives magical healing.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Diablo cornudo', 'Demonio', 'Grande', '18', '178', '11', '{"id":"srd-horned-devil","name":"Diablo cornudo","type":"Demonio","size":"Grande","ac":18,"hp":178,"speed":"20 pies, vuelo 60 pies","cr":11,"stats":{"str":22,"dex":17,"con":21,"int":12,"wis":16,"cha":17},"abilities":"Devil''s Sight. Magical darkness doesn''t impede the devil''s darkvision. Magic Resistance. The devil has advantage on saving throws against spells and other magical effects. Sentidos: darkvision 120 ft., passive Perception 13. Idiomas: Infernal, telepathy 120 ft. Dados de golpe: 17d10+85 Armadura: natural armor","actions":"Multiattack. The devil makes three melee attacks: two with its fork and one with its tail. It can use Hurl Flame in place of any melee attack. Fork. Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 15 (2d8 + 6) piercing damage. Tail. Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 10 (1d8 + 6) piercing damage. If the target is a creature other than an undead or a construct, it must succeed on a DC 17 Constitution saving throw or lose 10 (3d6) hit points at the start of each of its turns due to an infernal wound. Each time the devil hits the wounded target with this attack, the damage dealt by the wound increases by 10 (3d6). Any creature can take an action to stanch the wound with a successful DC 12 Wisdom (Medicine) check. The wound also closes if the target receives magical healing. Hurl Flame. Ranged Spell Attack: +7 to hit, range 150 ft., one target. Hit: 14 (4d6) fire damage. If the target is a flammable object that isn''t being worn or carried, it also catches fire.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Diablo de cadenas', 'Demonio', 'Mediano', '16', '85', '11', '{"id":"srd-chain-devil","name":"Diablo de cadenas","type":"Demonio","size":"Mediano","ac":16,"hp":85,"speed":"30 pies","cr":11,"stats":{"str":18,"dex":15,"con":18,"int":11,"wis":12,"cha":14},"abilities":"Devil''s Sight. Magical darkness doesn''t impede the devil''s darkvision. Magic Resistance. The devil has advantage on saving throws against spells and other magical effects. Sentidos: darkvision 120 ft., passive Perception 8. Idiomas: Infernal, telepathy 120 ft. Dados de golpe: 10d8+40 Armadura: natural armor","actions":"Multiattack. The devil makes two attacks with its chains. Chain. Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) slashing damage. The target is grappled (escape DC 14) if the devil isn''t already grappling a creature. Until this grapple ends, the target is restrained and takes 7 (2d6) piercing damage at the start of each of its turns. Animate Chains (Recharges after a Short or Long Rest). Up to four chains the devil can see within 60 feet of it magically sprout razor-edged barbs and animate under the devil''s control, provided that the chains aren''t being worn or carried.\nEach animated chain is an object with AC 20, 20 hit points, resistance to piercing damage, and immunity to psychic and thunder damage. When the devil uses Multiattack on its turn, it can use each animated chain to make one additional chain attack. An animated chain can grapple one creature of its own but can''t make attacks while grappling. An animated chain reverts to its inanimate state if reduced to 0 hit points or if the devil is incapacitated or dies.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Diablo de hielo', 'Demonio', 'Grande', '18', '180', '14', '{"id":"srd-ice-devil","name":"Diablo de hielo","type":"Demonio","size":"Grande","ac":18,"hp":180,"speed":"40 pies","cr":14,"stats":{"str":21,"dex":14,"con":18,"int":18,"wis":15,"cha":18},"abilities":"Devil''s Sight. Magical darkness doesn''t impede the devil''s darkvision. Magic Resistance. The devil has advantage on saving throws against spells and other magical effects. Sentidos: blindsight 60 ft., darkvision 120 ft., passive Perception 12. Idiomas: Infernal, telepathy 120 ft. Dados de golpe: 19d10+76 Armadura: natural armor","actions":"Multiattack. The devil makes three attacks: one with its bite, one with its claws, and one with its tail. Bite. Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) piercing damage plus 10 (3d6) cold damage. Claws. Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 10 (2d4 + 5) slashing damage plus 10 (3d6) cold damage. Tail. Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 12 (2d6 + 5) bludgeoning damage plus 10 (3d6) cold damage. Wall of Ice. The devil magically forms an opaque wall of ice on a solid surface it can see within 60 feet of it. The wall is 1 foot thick and up to 30 feet long and 10 feet high, or it''s a hemispherical dome up to 20 feet in diameter.\nWhen the wall appears, each creature in its space is pushed out of it by the shortest route. The creature chooses which side of the wall to end up on, unless the creature is incapacitated. The creature then makes a DC 17 Dexterity saving throw, taking 35 (10d6) cold damage on a failed save, or half as much damage on a successful one.\nThe wall lasts for 1 minute or until the devil is incapacitated or dies. The wall can be damaged and breached; each 10-foot section has AC 5, 30 hit points, vulnerability to fire damage, and immunity to acid, cold, necrotic, poison, and psychic damage. If a section is destroyed, it leaves behind a sheet of frigid air in the space the wall occupied. Whenever a creature finishes moving through the frigid air on a turn, willingly or otherwise, the creature must make a DC 17 Constitution saving throw, taking 17 (5d6) cold damage on a failed save, or half as much damage on a successful one. The frigid air dissipates when the rest of the wall vanishes.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Diablo de huesos', 'Demonio', 'Grande', '19', '142', '9', '{"id":"srd-bone-devil","name":"Diablo de huesos","type":"Demonio","size":"Grande","ac":19,"hp":142,"speed":"40 pies, vuelo 40 pies","cr":9,"stats":{"str":18,"dex":16,"con":18,"int":13,"wis":14,"cha":16},"abilities":"Devil''s Sight. Magical darkness doesn''t impede the devil''s darkvision. Magic Resistance. The devil has advantage on saving throws against spells and other magical effects. Sentidos: darkvision 120 ft., passive Perception 9. Idiomas: Infernal, telepathy 120 ft. Dados de golpe: 15d10+60 Armadura: natural armor","actions":"Multiattack. The devil makes three attacks: two with its claws and one with its sting. Claw. Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 8 (1d8 + 4) slashing damage. Sting. Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 13 (2d8 + 4) piercing damage plus 17 (5d6) poison damage, and the target must succeed on a DC 14 Constitution saving throw or become poisoned for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Djinni', 'Elemental', 'Grande', '17', '161', '11', '{"id":"srd-djinni","name":"Djinni","type":"Elemental","size":"Grande","ac":17,"hp":161,"speed":"30 pies, vuelo 90 pies","cr":11,"stats":{"str":21,"dex":15,"con":22,"int":15,"wis":16,"cha":20},"abilities":"Elemental Demise. If the djinni dies, its body disintegrates into a warm breeze, leaving behind only equipment the djinni was wearing or carrying. Innate Spellcasting. The djinni''s innate spellcasting ability is Charisma (spell save DC 17, +9 to hit with spell attacks). It can innately cast the following spells, requiring no material components:\n\nAt will: detect evil and good, detect magic, thunderwave\n3/day each: create food and water (can create wine instead of water), tongues, wind walk\n1/day each: conjure elemental (air elemental only), creation, gaseous form, invisibility, major image, plane shift Variant: Genie Powers. Genies have a variety of magical capabilities, including spells. A few have even greater powers that allow them to alter their appearance or the nature of reality.\n\n**Disguises.** Some genies can veil themselves in illusion to pass as other similarly shaped creatures. Such genies can innately cast the disguise self spell at will, often with a longer duration than is normal for that spell. Mightier genies can cast the true polymorph spell one to three times per day, possibly with a longer duration than normal. Such genies can change only their own shape, but a rare few can use the spell on other creatures and objects as well.\n**Wishes.** The genie power to grant wishes is legendary among mortals. Only the most potent genies, such as those among the nobility, can do so. A particular genie that has this power can grant one to three wishes to a creature that isn''t a genie. Once a genie has granted its limit of wishes, it can''t grant wishes again for some amount of time (usually 1 year). and cosmic law dictates that the same genie can expend its limit of wishes on a specific creature only once in that creature''s existence.\nTo be granted a wish, a creature within 60 feet of the genie states a desired effect to it. The genie can then cast the wish spell on the creature''s behalf to bring about the effect. Depending on the genie''s nature, the genie might try to pervert the intent of the wish by exploiting the wish''s poor wording. The perversion of the wording is usually crafted to be to the genie''s benefit. Sentidos: darkvision 120 ft., passive Perception 13. Idiomas: Auran Dados de golpe: 14d10+84 Armadura: natural armor","actions":"Multiattack. The djinni makes three scimitar attacks. Scimitar. Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) slashing damage plus 3 (1d6) lightning or thunder damage (djinni''s choice). Create Whirlwind. A 5-foot-radius, 30-foot-tall cylinder of swirling air magically forms on a point the djinni can see within 120 feet of it. The whirlwind lasts as long as the djinni maintains concentration (as if concentrating on a spell). Any creature but the djinni that enters the whirlwind must succeed on a DC 18 Strength saving throw or be restrained by it. The djinni can move the whirlwind up to 60 feet as an action, and creatures restrained by the whirlwind move with it. The whirlwind ends if the djinni loses sight of it.\nA creature can use its action to free a creature restrained by the whirlwind, including itself, by succeeding on a DC 18 Strength check. If the check succeeds, the creature is no longer restrained and moves to the nearest space outside the whirlwind.","alignment":"Caótico bueno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Doppelganger', 'Monstruosidad', 'Mediano', '14', '52', '3', '{"id":"srd-doppelganger","name":"Doppelganger","type":"Monstruosidad","size":"Mediano","ac":14,"hp":52,"speed":"30 pies","cr":3,"stats":{"str":11,"dex":18,"con":14,"int":11,"wis":12,"cha":14},"abilities":"Shapechanger. The doppelganger can use its action to polymorph into a Small or Medium humanoid it has seen, or back into its true form. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies. Ambusher. The doppelganger has advantage on attack rolls against any creature it has surprised. Surprise Attack. If the doppelganger surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 10 (3d6) damage from the attack. Sentidos: darkvision 60 ft., passive Perception 11. Idiomas: Common Dados de golpe: 8d8+16","actions":"Multiattack. The doppelganger makes two melee attacks. Slam. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) bludgeoning damage. Read Thoughts. The doppelganger magically reads the surface thoughts of one creature within 60 ft. of it. The effect can penetrate barriers, but 3 ft. of wood or dirt, 2 ft. of stone, 2 inches of metal, or a thin sheet of lead blocks it. While the target is in range, the doppelganger can continue reading its thoughts, as long as the doppelganger''s concentration isn''t broken (as if concentrating on a spell). While reading the target''s mind, the doppelganger has advantage on Wisdom (Insight) and Charisma (Deception, Intimidation, and Persuasion) checks against the target.","alignment":"Sin alineamiento","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Dragón azul adulto', 'Dragón', 'Enorme', '19', '225', '16', '{"id":"srd-adult-blue-dragon","name":"Dragón azul adulto","type":"Dragón","size":"Enorme","ac":19,"hp":225,"speed":"40 pies, vuelo 80 pies, excavación 30 pies","cr":16,"stats":{"str":25,"dex":10,"con":23,"int":16,"wis":15,"cha":19},"abilities":"Legendary Resistance (3/Day). If the dragon fails a saving throw, it can choose to succeed instead. Sentidos: blindsight 60 ft., darkvision 120 ft., passive Perception 22. Idiomas: Common, Draconic Dados de golpe: 18d12+108 Armadura: natural armor","actions":"Multiattack. The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws. Bite. Melee Weapon Attack: +12 to hit, reach 10 ft., one target. Hit: 18 (2d10 + 7) piercing damage plus 5 (1d10) lightning damage. Claw. Melee Weapon Attack: +12 to hit, reach 5 ft., one target. Hit: 14 (2d6 + 7) slashing damage. Tail. Melee Weapon Attack: +12 to hit, reach 15 ft., one target. Hit: 16 (2d8 + 7) bludgeoning damage. Frightful Presence. Each creature of the dragon''s choice that is within 120 ft. of the dragon and aware of it must succeed on a DC 17 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours. Lightning Breath (Recharge 5-6). The dragon exhales lightning in a 90-foot line that is 5 ft. wide. Each creature in that line must make a DC 19 Dexterity saving throw, taking 66 (12d10) lightning damage on a failed save, or half as much damage on a successful one. Detect (legendaria). The dragon makes a Wisdom (Perception) check. Tail Attack (legendaria). The dragon makes a tail attack. Wing Attack (Costs 2 Actions) (legendaria). The dragon beats its wings. Each creature within 10 ft. of the dragon must succeed on a DC 20 Dexterity saving throw or take 14 (2d6 + 7) bludgeoning damage and be knocked prone. The dragon can then fly up to half its flying speed. Acciones legendarias. The dragon can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The dragon regains spent legendary actions at the start of its turn.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Dragón azul anciano', 'Dragón', 'Colosal', '22', '481', '23', '{"id":"srd-ancient-blue-dragon","name":"Dragón azul anciano","type":"Dragón","size":"Colosal","ac":22,"hp":481,"speed":"40 pies, vuelo 80 pies, excavación 40 pies","cr":23,"stats":{"str":29,"dex":10,"con":27,"int":18,"wis":17,"cha":21},"abilities":"Legendary Resistance (3/Day). If the dragon fails a saving throw, it can choose to succeed instead. Sentidos: blindsight 60 ft., darkvision 120 ft., passive Perception 27. Idiomas: Common, Draconic Dados de golpe: 26d20+208 Armadura: natural armor","actions":"Multiattack. The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws. Bite. Melee Weapon Attack: +16 to hit, reach 15 ft., one target. Hit: 20 (2d10 + 9) piercing damage plus 11 (2d10) lightning damage. Claw. Melee Weapon Attack: +16 to hit, reach 10 ft., one target. Hit: 16 (2d6 + 9) slashing damage. Tail. Melee Weapon Attack: +16 to hit, reach 20 ft., one target. Hit: 18 (2d8 + 9) bludgeoning damage. Frightful Presence. Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a DC 20 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours. Lightning Breath (Recharge 5-6). The dragon exhales lightning in a 120-foot line that is 10 feet wide. Each creature in that line must make a DC 23 Dexterity saving throw, taking 88 (16d10) lightning damage on a failed save, or half as much damage on a successful one. Detect (legendaria). The dragon makes a Wisdom (Perception) check. Tail Attack (legendaria). The dragon makes a tail attack. Wing Attack (Costs 2 Actions) (legendaria). The dragon beats its wings. Each creature within 15 ft. of the dragon must succeed on a DC 24 Dexterity saving throw or take 16 (2d6 + 9) bludgeoning damage and be knocked prone. The dragon can then fly up to half its flying speed. Acciones legendarias. The dragon can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The dragon regains spent legendary actions at the start of its turn.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
  ('', 'Dragón azul joven', 'Dragón', 'Grande', '18', '152', '9', '{"id":"srd-young-blue-dragon","name":"Dragón azul joven","type":"Dragón","size":"Grande","ac":18,"hp":152,"speed":"40 pies, vuelo 80 pies, excavación 40 pies","cr":9,"stats":{"str":21,"dex":10,"con":19,"int":14,"wis":13,"cha":17},"abilities":"Sentidos: blindsight 30 ft., darkvision 120 ft., passive Perception 19. Idiomas: Common, Draconic Dados de golpe: 16d10+64 Armadura: natural armor","actions":"Multiattack. The dragon makes three attacks: one with its bite and two with its claws. Bite. Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 16 (2d10 + 5) piercing damage plus 5 (1d10) lightning damage. Claw. Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) slashing damage. Lightning Breath (Recharge 5-6). The dragon exhales lightning in an 60-foot line that is 5 feet wide. Each creature in that line must make a DC 16 Dexterity saving throw, taking 55 (10d10) lightning damage on a failed save, or half as much damage on a successful one.","alignment":"Legal maligno","source":"srd-5.1"}'::jsonb, 'srd-5.1'),
